('page-e2ae99d4-4867-4f00-b5de-725583543af6', 21, 'heading', 'טיול לקהיר', 3, '[]', '[{"text":"טיול לקהיר","href":"/blog/cairo/"}]', null, null, null, null),
('page-e2ae99d4-4867-4f00-b5de-725583543af6', 22, 'paragraph', 'קהיר זו עיר בירתה של מצרים ולב לבה של מבקרים מכל העולם. טיול לקהיר הוא טיול מרתק במיוחד וכלל בתוכו המון אלמנטים תרבותיים והיסטוריים משולבים', null, '[]', '[]', null, null, null, null),
