('page-e2ae99d4-4867-4f00-b5de-725583543af6', 24, 'heading', 'טיול לפירמידות', 3, '[]', '[{"text":"טיול לפירמידות","href":"/blog/pyramids/"}]', null, null, null, null),
('page-e2ae99d4-4867-4f00-b5de-725583543af6', 25, 'paragraph', 'בין הסמלים המובהקים לתרבות מצרים העתיקה, הן הפירמידות המפורסמות בכל העולם אשר נבנו בתקופת הממלכה הקדומה ותקופת הממלכה התיכונה לפני אלפי שנים. הן בעלות היסטוריה', null, '[]', '[]', null, null, null, null),
