('page-e2ae99d4-4867-4f00-b5de-725583543af6', 33, 'heading', 'מקדשי דנדרה / זודיאק של דנדרה', 3, '[]', '[{"text":"מקדשי דנדרה / זודיאק של דנדרה","href":"/blog/dendera-zodiac/"}]', null, null, null, null),
