('page-e2ae99d4-4867-4f00-b5de-725583543af6', 36, 'heading', 'טיול לממפיס סקארה', 3, '[]', '[{"text":"טיול לממפיס סקארה","href":"/blog/memphis-saqqara/"}]', null, null, null, null),
('page-e2ae99d4-4867-4f00-b5de-725583543af6', 37, 'paragraph', 'טיול לממפיס וסקארה הוא טיול ייחודי המשלב שני אתרים היסטוריים ומשמעותיים במצריים ובתרבות המצרית. ממפיס הייתה בירת מצרים העתיקה, וסקארה הייתה עיר הקברים שלה. בממפיס', null, '[]', '[]', null, null, null, null),
