('page-e2ae99d4-4867-4f00-b5de-725583543af6', 39, 'heading', 'טיול לכנסייה תלויה / כנסיית אל-מועלק', 3, '[]', '[{"text":"טיול לכנסייה תלויה / כנסיית אל-מועלק","href":"/blog/hanging-church/"}]', null, null, null, null),
('page-e2ae99d4-4867-4f00-b5de-725583543af6', 40, 'paragraph', 'מסע בזמן להיסטוריה העתיקה של מצרים ישאיר אתכם פעורי פה ועד לגבול הבלתי נתפס. הסיורים המרהיבים של מצרים יגרמו לכם לחוות את מצרים כמו שלא', null, '[]', '[]', null, null, null, null),
('page-e2ae99d4-4867-4f00-b5de-725583543af6', 41, 'paragraph', 'להמשך קריאה »', null, '[]', '[{"text":"להמשך קריאה »","href":"/blog/uzbekistan-silk-road/"},{"text":"להמשך קריאה »","href":"/blog/china-cultural-journey/"},{"text":"להמשך קריאה »","href":"/blog/china-experience/"},{"text":"להמשך קריאה »","href":"/blog/beijing/"},{"text":"להמשך קריאה »","href":"/blog/athens/"},{"text":"להמשך קריאה »","href":"/blog/ancient-china-facts/"},{"text":"להמשך קריאה »","href":"/blog/ancient-greece-facts/"},{"text":"להמשך קריאה »","href":"/blog/cairo/"},{"text":"להמשך קריאה »","href":"/blog/pyramids/"},{"text":"להמשך קריאה »","href":"/blog/aswan-dam/"},{"text":"להמשך קריאה »","href":"/blog/alexandria/"},{"text":"להמשך קריאה »","href":"/blog/dendera-zodiac/"},{"text":"להמשך קריאה »","href":"/blog/memphis-saqqara/"},{"text":"להמשך קריאה »","href":"/blog/hanging-church/"},{"text":"להמשך קריאה »","href":"/blog/abu-simbel/"}]', null, null, null, null),
('page-e2ae99d4-4867-4f00-b5de-725583543af6', 42, 'heading', 'טיול לאבו סימבל', 3, '[]', '[{"text":"טיול לאבו סימבל","href":"/blog/abu-simbel/"}]', null, null, null, null),
('page-e2ae99d4-4867-4f00-b5de-725583543af6', 43, 'paragraph', 'טיול לאבו סימבל הוא טיול קליל ומאוד כיפי לכלל המבקרים בה. אבו סימבל היא עיר קטנה ומלאה בקסם ושוכנת לא רחוק מגבול מצרים-סודאן ולצד נהר', null, '[]', '[]', null, null, null, null),
('page-e2ae99d4-4867-4f00-b5de-725583543af6', 44, 'paragraph', 'להמשך קריאה »', null, '[]', '[{"text":"להמשך קריאה »","href":"/blog/uzbekistan-silk-road/"},{"text":"להמשך קריאה »","href":"/blog/china-cultural-journey/"},{"text":"להמשך קריאה »","href":"/blog/china-experience/"},{"text":"להמשך קריאה »","href":"/blog/beijing/"},{"text":"להמשך קריאה »","href":"/blog/athens/"},{"text":"להמשך קריאה »","href":"/blog/ancient-china-facts/"},{"text":"להמשך קריאה »","href":"/blog/ancient-greece-facts/"},{"text":"להמשך קריאה »","href":"/blog/cairo/"},{"text":"להמשך קריאה »","href":"/blog/pyramids/"},{"text":"להמשך קריאה »","href":"/blog/aswan-dam/"},{"text":"להמשך קריאה »","href":"/blog/alexandria/"},{"text":"להמשך קריאה »","href":"/blog/dendera-zodiac/"},{"text":"להמשך קריאה »","href":"/blog/memphis-saqqara/"},{"text":"להמשך קריאה »","href":"/blog/hanging-church/"},{"text":"להמשך קריאה »","href":"/blog/abu-simbel/"}]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 0, 'paragraph', 'טיול לאבו סימבל הוא טיול קליל ומאוד כיפי לכלל המבקרים בה. אבו סימבל היא עיר קטנה ומלאה בקסם ושוכנת לא רחוק מגבול מצרים-סודאן ולצד נהר הנילוס. בעיר אבו סימבל מאוד קל לטייל בה ברגל והיא יעד נהדר לטיול יומי קליל וממלא באנרגיות טובות.', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 1, 'paragraph', 'אבו סימבל זהו אתר ארכיאולוגי אשר נמצא בעיר אבו סימבל והאתרים המרכזיים בהם ניתן לבקר הם שני המקדשים ההיסטוריים מקדש ראמסס השני ומקדש “הת’ור” של נפרטיטי כמעט ונשטפו על ידי מפלס המים העולה של הצטברות מי הנילוס מדרום לסכר אסואן (אשר נבנה למטרת אגירת המים מדרומו.', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 2, 'paragraph', 'שני המקדשים נבנו על ידי הפרעונים סתי הראשון ורעמסס השני, בין השנים 1284 לפנה”ס ל־1264 לפנה”ס לערך. המקדשים ניצלו ושוחזרו כאשר עבודות השימור החלו כבר בשנות ה-60 המוקדמות. יחד עם חברת טיולי העולם העתיק נחווה יחד את החוויה היוצאת דופן ונחיה את מצרים העתיקה ונרגיש את רוח הדברים לצד סיפורים מרהיבים ומלאים בהיסטוריה מצמררת.', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 3, 'paragraph', 'המקדש הגדול', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 4, 'paragraph', 'שער הכניסה למקדש הגדול נמצא בין שני פילונים שהוא הכניסה למקדש. בסמוך לפילונים ניתן לראות פסלים ענקיים המגדירים את הכניסה למקדש. הפסלים הללו הם 4 פסלים של רעמסס השני. בין רגליו של הפרעה מוצגים בני משפחתו בגודל קטן בהרבה ביחס אליו.', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 5, 'paragraph', 'המקדש הקטן', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 6, 'paragraph', 'זהו המקש שהוקדש למלכה נפרטרי אשתו החשובה של רעמסס השני, וזהו המקדש השני בהיסטוריה המצרית שהוקדש למלכה. המקדש הראשון הוקדש למלכה נפרטיטי. המקדש הקטן שוכן כ-100 מ”ר מהמקדש גדול של הפרעה. לצידי הכניסה למקדש תוכלו לראות פסלי ענק בגודל מעל 10 מטר. במרכז של כל שלישית פסלים נמצא פסל ענק של נפרטרי, הפסלים זהים בגודלם לפסלי רעמסס השני.', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 7, 'paragraph', 'טיולים נוספים בטיולי העולם העתיק', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 8, 'paragraph', 'בחברת טיולי העולם העתיק תוכלו להנות ממגוון של טיולים למצרים האגדית ולהנות מתרבות עוצרת נשימה, נופים, אטרקציות, שווקים, מסעדות ועוד, כמו:', null, '[]', '[]', null, null, null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 9, 'list', null, null, '[]', '[]', false, '[{"text":"טיול לפירמידות.","links":[],"children":[]},{"text":"טיול לקהיר.","links":[],"children":[]},{"text":"טיול לאלכסנדריה.","links":[],"children":[]},{"text":"סאכר אסואן ועוד.","links":[],"children":[]}]', null, null),
('page-32a0beb0-48a4-4812-b05f-9d3dc80d9df4', 10, 'paragraph', 'כל מה שנותר לכם, זה לפנות לצוות של טיולי העולם העתיק, לבחור את היעד המועדף עליכם ולתאם את הטיול שלכם', null, '[]', '[]', null, null, null, null),
('page-f3047d75-2bb0-4e63-8de0-bc4eaf27d68a', 0, 'paragraph', 'מסע בזמן להיסטוריה העתיקה של מצרים ישאיר אתכם פעורי פה ועד לגבול הבלתי נתפס. הסיורים המרהיבים של מצרים יגרמו לכם לחוות את מצרים כמו שלא חוויתם אף פעם. עם הטיולים של חברת טיולי העולם העתיק תוכלו סוף סוף להגשים את החלום, ולטעום מיעדים מובחרים במצרים הכוללים תרבות, סיורים לאתרים היסטוריים עתיקים, שווקים, מסעדות אותנטיות ועדכניות ועוד מגוון רחב של אטרקציות ופעילויות לאורך השהות שלכם במצריים.', null, '[]', '[]', null, null, null, null),
('page-f3047d75-2bb0-4e63-8de0-bc4eaf27d68a', 1, 'paragraph', 'טיול לכנסייה תלויה כנסיית אל-מועלק הוא אחד הטיולים המרהיבים של מצריים, והיא כנסייה קופטית ישנה השוכנת בעיר קהיר העתיקה. הכנסייה נבנתה על שער הדרומי של מצודת בבל הרומית, ומשום כך נראית כאילו היא מושעה באוויר. השם אל-מועלק משמעו “המושעה” בערבית.', null, '[]', '[]', null, null, null, null),
('page-f3047d75-2bb0-4e63-8de0-bc4eaf27d68a', 2, 'paragraph', 'הכנסייה מוקדשת למרים הבתולה, והיא אחת משבע כנסיות שנמצאות באתר הנקרא “מחוז הכנסיות”. הכנסייה התלויה הנוכחית נחשבת למקומה בפטריארכיה של יצחק מאלכסנדריה, האפיפיור הקופטי שכיהן בתפקידו במאה ה -7. בשנת 1047 הכנסיה נקבעה כמקום מגוריו הרשמי של האפיפיור הקופטי האורתודוקסי לאחר שכיבוש מצרים מוסלמי גרם להעברת בירת מצרים מאלכסנדריה לקהיר.', null, '[]', '[]', null, null, null, null),
('page-f3047d75-2bb0-4e63-8de0-bc4eaf27d68a', 3, 'paragraph', 'מה בעיר?', null, '[]', '[]', null, null, null, null),
('page-f3047d75-2bb0-4e63-8de0-bc4eaf27d68a', 4, 'paragraph', 'קהיר זו עיר מדהימה ביופייה והיא משלבת בתוכה אזורים שונים כמו העיר העתיקה והעיר העדכנית לצד שווקים המלאים בכל טוב, מסעדות עם מבחר גדול של אוכל מגוון, שמנים ארומטיים, כלים, מוצרי עור לצד המודרני המשלב מבנים מודרניים, חנויות ועוד. בקהיר ניתן לבקר בהמון אתרים היסטוריים כמו אתרים היסטוריים וקדושים, מוזיאונים, קניונים מרהיבים ולצאת למסע קניות משגע.', null, '[]', '[]', null, null, null, null),
('page-f3047d75-2bb0-4e63-8de0-bc4eaf27d68a', 5, 'paragraph', 'למי זה מתאים?', null, '[]', '[]', null, null, null, null),
('page-f3047d75-2bb0-4e63-8de0-bc4eaf27d68a', 6, 'paragraph', 'הטיול למצרים מתאים כמעט עבור כל אחד ואחת וניתן להנות מכל דבר לאורך כל הטיול. הטיול מתאים לזוגות צעירים ולמשפחות, לזוגות מבוגרים יותר, לקבוצות גדולות וקטנות. טיול למצריים יכול להתאים גם לחברות וארגונים ולהשתמש בטיול למצריים כי תמרוקים עבור צוות העובדים, צוות מנהלים או שי יוקרתי וייחודי במיוחד להורים שלכם או למישהו אהוב ויקר לליבכם שרוצים לפנק.', null, '[]', '[]', null, null, null, null),
('page-f3047d75-2bb0-4e63-8de0-bc4eaf27d68a', 7, 'paragraph', 'לקבלת פרטים נוספים עבור הטיולים שלנו במצריים, הנכם מוזמנים להגיע לטיולי העולם העתיק, והצוות האדיב שלנו יכוון אתכם ויעזור לכם לבחור את היעד הבא שלכם.', null, '[]', '[]', null, null, null, null),
('page-abef17c9-f313-4611-8203-e47d306b916a', 0, 'paragraph', 'טיול לממפיס וסקארה הוא טיול ייחודי המשלב שני אתרים היסטוריים ומשמעותיים במצריים ובתרבות המצרית. ממפיס הייתה בירת מצרים העתיקה, וסקארה הייתה עיר הקברים שלה. בממפיס נמצא פסל ענק של רעמסס השני, ובסקארה נמצאת הפירמידה הראשונה שנבנתה בהיסטוריה, הפירמידה של ג’וסר.', null, '[]', '[]', null, null, null, null),
('page-abef17c9-f313-4611-8203-e47d306b916a', 1, 'paragraph', 'עם חברת טיולי העולם העתיק אתם תחוו טיול מלא בחוויות בלתי נשכחות לאורך כל הטיול. הצוות המקצועי והנדיב יגרמו לכם לטעום ממצריים העתיקה באופן ייחודי ויחד נבקר באתרים היסטוריים רבים, מוזיאונים, שווקים ועוד פעילויות שונות.', null, '[]', '[]', null, null, null, null),
('page-abef17c9-f313-4611-8203-e47d306b916a', 2, 'paragraph', 'ממפיס', null, '[]', '[]', null, null, null, null),
('page-abef17c9-f313-4611-8203-e47d306b916a', 3, 'paragraph', 'ממפיס הייתה עיר במצרים העתיקה, ושרידיה שוכנים על הגדה המערבית של הנילוס, בקצה הדרומי של דלתת הנילוס, כ־20 ק”מ דרומית לקהיר, ליד העיר המצרית המודרנית מית־רחינה. התושבים במהלך השנים עשו שימוש משני באבני הבניין של ממפיס, נשארו שרידים מעטים באתר. בהמשך נחשפו המקדשים של האלים פתח ואפיס הגדולים. כמו כן נחשפו במקום מספר פסלים בגובה של 4 מטר. כיום נמצא בממפיס אתר המשמש כמוזיאון פתוח הכולל ממצאים מתקופת מצרים העתיקה.', null, '[]', '[]', null, null, null, null),
('page-abef17c9-f313-4611-8203-e47d306b916a', 4, 'paragraph', 'סקארה', null, '[]', '[]', null, null, null, null),
('page-abef17c9-f313-4611-8203-e47d306b916a', 5, 'paragraph', 'סַקַארָה הוא אתר קבורה עתיק מאוד סמוך לקהיר שהייתה עיר הקברים של ממפיס, בירת מצרים העתיקה. עיר המתים הוקמה על ידי המלך ג’וסר. זהו אחד מאתרי הקבורה הפרעוניים העתיקים והחשובים ביותר שבמצרים. בסקארה נמצאים קברים, מקדשים ופירמידות של מלכי ונשיות מלכי משלושת המשפחות הראשונות של מצרים.', null, '[]', '[]', null, null, null, null),
('page-abef17c9-f313-4611-8203-e47d306b916a', 6, 'paragraph', 'למי מתאים טיול לממפיס סקארה?', null, '[]', '[]', null, null, null, null),
('page-abef17c9-f313-4611-8203-e47d306b916a', 7, 'paragraph', 'טיול לממפיס סקארה מתאים לאוכלוסיה מגוונת ומתאימה לאנשים בגילאים שונים. הטיול יכול להתאים לזוגות שמחפשים טיול בסגנון אחרי ומרתק, זוגות מבוגרים יותר שסוף סוף יש להם זמן פנוי ורוצים לבלות יחד ולצבור עוד חוויות, קבוצות קטנות וקבוצות גדולות. גם חברות בסדרי גודל השונים, ארגונים וגופים נוספים יכולים להעניק טיול למצרים לצוותי העובדים שלהם, קבוצות של מנהלים ואנשי פתח של הארגון. טיול זה יכול להיות מתנה מושלמת עבור מישהו שאתם מאוד אוהבים ומחפשים מלתת להם מתנה שונה, מקורית וייחודית. עם חברת טיולי העולם העתיק אתם יכולים להגשים את החלום ולחוות רגעים בלתי נשכחים. הצוות שלנו יכוון אתכם ויתאים עבורכם את המסלול המושלם.', null, '[]', '[]', null, null, null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 0, 'paragraph', 'קהיר זו עיר בירתה של מצרים ולב לבה של מבקרים מכל העולם. טיול לקהיר הוא טיול מרתק במיוחד וכלל בתוכו המון אלמנטים תרבותיים והיסטוריים משולבים עם התרבות המודרנית לצד מנהגים עתיקים אשר נשמרו ועוברים מדור לדור בשלמותם. קהיר היא עיר מאוד מגוונת וכוללת בתוכה אלמנטים אפריקאים, מזרחיים ואירופאים כאחד. זו עיר צפופה מאוד המונה כ-9.6 מליון תושבים, והיא אחת המרתקות והמסעירות באזורינו.', null, '[]', '[]', null, null, null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 1, 'paragraph', 'קהיר ממוקמת בצפון מצרים, לגדות נהר הנילוס מתחלקת לשני חלקים לא שווים: העיר העתיקה אשר בנויה באופן צפוף ואותנטי, והעיר החדשה אשר בנויה בסגנון אירופאי מודרני.', null, '[]', '[]', null, null, null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 2, 'paragraph', 'אתרים חשובים בעיר קהיר', null, '[]', '[]', null, null, null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 3, 'paragraph', 'טיול לקהיר הוא לא סתם טיול רגיל, אלא מסע אל העבר בלתי נשכח בעל היסטוריה יוצאת דופן ובלתי נתפסת. בעיר קהיר ישנם כמה אתרים מאוד חשובים בהיסטוריה המצרית ומהווים חלק בלתי נפרד מההיסטוריה המצרית, והם:', null, '[]', '[]', null, null, null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 4, 'list', null, null, '[]', '[]', false, '[{"text":"המוזיאון המצרי ובו נמצא אוסף הפריטים הגדול ביותר ממצרים העתיקה.","links":[],"children":[]},{"text":"המוזיאון המצרי הגדול המכונה גם מוזיאון גיזה, בו ישנם ריכוז ותיעוד האוסף הציבורי הגדול ביותר לתרבות מצרים העתיקה.","links":[],"children":[]},{"text":"מצודת צלאח א-דין היא מצודה מתקופת ימי הביניים שנבנתה בקהיר.","links":[],"children":[]},{"text":"שוק חאן אל-חלילי אשר תמצאו בו שלל של פריטים מרהיבים, ביגוד בעבודות יד ומוצרי עור, שמנים מבושמים מיצריים ועוד.","links":[],"children":[]},{"text":"קהיר העתיקה בה נסייר ונתרשם מכל היופי העתיק של קהיר, ובית הכנסת בן עזרא.","links":[],"children":[]},{"text":"סיורים בשכונות מיוחדות ויוצאות דופן, כמו שכונות כפריות וגם שכונות מודרניות ועשירות.","links":[],"children":[]}]', null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 5, 'paragraph', 'אנו חברת טיולי העולם העתיק עושים את הכול על מנת להביא לכם את הטיולים הכי שווים ועשירים בחוויות ומקומות יוצאי דופן אשר משלבים בתוכו המון אלמנטים ואטרקציות לצד תרבות מגוונת והיסטוריה ייחודית. בטיולים שלנו תטעמו מכל דבר ומכל פינה מצרית, כך שלא תצאו מאיתנו ללא מזכרות לכל החיים.', null, '[]', '[]', null, null, null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 6, 'paragraph', 'בחברת טיולי העולם העתיק תוכלו להנות מטיולים ליעדים שונים במצרים כמו:', null, '[]', '[]', null, null, null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 7, 'list', null, null, '[]', '[]', false, '[{"text":"טיול לאלכסנדריה","links":[],"children":[]},{"text":"טיול לפירמידות העתיקות","links":[],"children":[]},{"text":"טיול לאבו סימבל","links":[],"children":[]},{"text":"טיול לסכר אסואן ועוד.","links":[],"children":[]}]', null, null),
('page-8f0d4e17-ba3f-4ff0-ad60-5097b256cfd7', 8, 'paragraph', 'אל תחמיצו את ההזדמנות לחוות חוויה בלתי נשכחת, והבטיחו את מקומכם כבר בטיול הקרוב לאחד היעדים הפופולריים במצרים המרהיבה.', null, '[]', '[]', null, null, null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 0, 'paragraph', 'טיול לאלכסנדריה זהו טיול מאוד חשוב מכלל הטיול למצרים, מכיוון שמדובר בעיר נמל של מצרים והיא עיר הכי חשובה בהיסטוריה המצרית ובעלת היסטוריה עתיקה מאוד עשירה.', null, '[]', '[]', null, null, null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 1, 'paragraph', 'עיר אלכסנדריה נוסדה בידי אלכסנדר מוקדון בשנת 334 לפנה”ס והוא קרא לה על שמו. אלכסנדריה הייתה לפוליס יווני אופיינית, מלאה בגנים מרהיבים ובבנייני ציבור מאוד מפוארים לאותה התקופה. למרבה צער כמעט דבר לא שרד מהתקופה העתיקה.', null, '[]', '[]', null, null, null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 2, 'paragraph', 'בסמוך להתחלת הספירה של הנוצרים, עיר אלכסנדריה נחשבה למרכז המדע והחכמה בעולם העתיק, והיא העיר השנייה בגודל של האימפריה הרומית אחרי רומא וגם היום. כיום העיר אלכסנדריה מונה כ-5.2 מיליון בני אדם. והיא אחראית על כ-80% מהיצוא והיבוא של מצרים בזכות המיקום שלה על חוף הים בעלת כ-32 ק”מ של חוף הים התיכון.', null, '[]', '[]', null, null, null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 3, 'paragraph', 'היכן מסיירים באלכסנדריה?', null, '[]', '[]', null, null, null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 4, 'paragraph', 'חברת טיולי העולם העתיק דואגים להביא לכם את הטיולים הכי ייחודיים ובהם טיול לאלכסנדריה אשר יכלול בתוכו המון נקודות בהן ניתן לבקר ולהתרשם, לחוות תרבות והיסטוריה לצד בילויים מקומיים ואתרי מבקרים מודרניים, כמו למשל:', null, '[]', '[]', null, null, null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 5, 'list', null, null, '[]', '[]', false, '[{"text":"גנים מטופחים ומלאים בירוק ומנזרים.","links":[],"children":[]},{"text":"מוזיאונים שונים וייחודיים.","links":[],"children":[]},{"text":"‪.בניינים ארכיטקטוניים וגשרים","links":[],"children":[]},{"text":"‪.אתרי עתיקות ואתרים היסטוריים","links":[],"children":[]},{"text":"טיילות וחופי ים.","links":[],"children":[]},{"text":"מרכזי קניות ושווקים.","links":[],"children":[]},{"text":"תרבות קולינרית מלאה במאכלים מיוחדים ואותנטיים לצד מטבח מודרני ועוד המון מרכזי מבקרים ונקודות בעלות אופי יוצא דופן.","links":[],"children":[]}]', null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 6, 'paragraph', 'יעדים פופולריים נוספים במצרים', null, '[]', '[]', null, null, null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 7, 'paragraph', 'עם חברת טיולי העולם העתיק תוכלו להנות ממגוון עשיר של טיולים למצרים ותוכלו לבקר ביעדים מאוד פופולריים וייחודיים כמו:', null, '[]', '[]', null, null, null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 8, 'list', null, null, '[]', '[]', false, '[{"text":"טיול לפירמידות העתיקות והמפורסמות בכל העולם.","links":[],"children":[]},{"text":"טיול לעיר הבירה של מצריים קהיר.","links":[],"children":[]},{"text":"טיול מרהיב הכנסייה התלויה וביקור במצודת בבילון (בבל) הקדומה.","links":[],"children":[]},{"text":"טיול למקדשי אבו סימבול השוכנים בעיר אבו סימבול במרחק נסיעה מהעיר קהיר ועם תצפיות לאורך הדרך הכוללים פסלי ענק.","links":[],"children":[]}]', null, null),
('page-0ece30a3-48a0-4586-bed3-100457f83c8d', 9, 'paragraph', 'אנו בטיולי העולם העתיק נדאג שלא יחסר לכם דבר בטיול לאלכסנדריה ותוכלו להנות מכל פעילות לאורך הטיול שלכם, נדאג שתחזרו הביתה עם תיק ענק שך חוויות ומזכרות אשר ילוו אתכם לאורך כל החיים. כל מה שנשאר לכם לעשות זה לבחור את היעד המעניין אתכם ולהבטיח לעצמכם את מקומכם איתנו כבר בטיול הקרוב למצריים.', null, '[]', '[]', null, null, null, null),
('page-7f6996d9-3dde-4d7a-8d00-5309944361a2', 0, 'paragraph', 'מקדש דנדרה זהו מקדש מצרי מאוד עתיק והוא אחד מהמקדשים העתיקים השמורים ביותר במצרים שהוקדש לאלה חתחור שהיא אלת היופי והאהבה , השוכן על הגדה המערבית של נהר הנילוס כ-4 ק”מ מהנהר, כ-2.5 ק”מ דרומית-מערבית לעיר דנדרה שבמצרים העליונה, וכ-60 ק”מ צפונית ללוקסור.', null, '[]', '[]', null, null, null, null),
('page-7f6996d9-3dde-4d7a-8d00-5309944361a2', 1, 'paragraph', 'המקדש נבנה בתקופה התלמיית ונשלם בתקופה הרומית, והוא אחד מהמקדשים המצריים השמורים ביותר בעולם. במתחם המקדש תוכלו לראות תבליטים עתיקים, כתובות קדומות, סמלים ואמנות של אותה התקופה העתיקה והמיוחדת.', null, '[]', '[]', null, null, null, null),
('page-7f6996d9-3dde-4d7a-8d00-5309944361a2', 2, 'paragraph', 'אחד מהאלמנטים הייחודיים של המקדש הוא גלגל המזלות של מקדשי דנדרה, שמראה את החיבור בין האסטרונומיה המצרית לאסטרולוגיה היוונית. גלגל המזלות המפוסל של דנדרה הוא תבליט מצרי ידוע מתקרת הפרונאוס (או האכסדרה) של קפלה המוקדשת לאוזיריס במקדש חתור בדנדרה, המכיל תמונות של מזל שור (השור) והמאזניים ועוד. זודיאק דה דנדרה עם 48 קבוצות הכוכבים של קלאודיוס תלמאוס מזוהים בבירור בין 72 קבוצות הכוכבים הנוכחיות בגלגל המזלות הזה.', null, '[]', '[]', null, null, null, null),
('page-7f6996d9-3dde-4d7a-8d00-5309944361a2', 3, 'paragraph', 'מקדש האלה חתחור', null, '[]', '[]', null, null, null, null),
('page-7f6996d9-3dde-4d7a-8d00-5309944361a2', 4, 'paragraph', 'מקדש האלה חתחור הוא המבנה המרכזי באתר. המתחם מתחיל באולם היפוסטיל גדול הכולל 24 עמודים המסודרים ב-4 שורות, וכל עמוד אשר נמצא באולם, נושא כותרת עם פניה של האלה חתחור בעיצוב של פני-פרה. כל הכותרות נהרסו כבר בתקופה ההיא, אך בקטעים רבים מהתקרה של המבנה שרד הצבעה המקורי. המקדש עוטר בתקופתו של הקיסר הרומי טיבריוס בשנת 34 לספירה.', null, '[]', '[]', null, null, null, null),
('page-7f6996d9-3dde-4d7a-8d00-5309944361a2', 5, 'paragraph', 'טיולים נוספים של עמק המכלים', null, '[]', '[]', null, null, null, null),
('page-7f6996d9-3dde-4d7a-8d00-5309944361a2', 6, 'paragraph', 'חברת טיולי העולם העתיק מתמחה בטיולים היסטוריים ועוצרי נשימה ליעדים נבחרים במצרים, ויחד עם המדריכים שלנו תוכלו לחוות חוויה בלתי נשכחת אשר תלווה אתכם לאורך תקופה ארוכת שנים. מעבר לטיול למקדשי דנדרה, תוכלו להנות מיעדים אטרקטיביים נוספים, כמו:', null, '[]', '[]', null, null, null, null),
('page-7f6996d9-3dde-4d7a-8d00-5309944361a2', 7, 'list', null, null, '[]', '[]', false, '[{"text":"טיול עוצר נשימה לפירמידות המדוברות והעתיקות.","links":[],"children":[]},{"text":"טיול מרהיב לאלכסנדריה.","links":[],"children":[]},{"text":"טיול לקהיר המשלבת בתוכה היסטוריה עתיקה לצד תקופה עדכנית.","links":[],"children":[]},{"text":"טיול לסכר אסואן שהוא מערכת של שני סכרים על נהר הנילוס המכונים “סכר אסואן הגבוה” ו”סכר אסואן הנמוך ועוד, כל מה שנותר לכם, זה להגיע עלינו לטיולי העולם העתיק ולתאם עבורכם את הטיול הבא שלכם.","links":[],"children":[]}]', null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 0, 'paragraph', 'סכר אסואן הוא מערכת של שני סכרים על נהר הנילוס המכונים “סכר אסואן הגבוה” ו”סכר אסואן הנמוך” שממוקמים סמוך לאסואן שבמצרים ומשמשים לאגירת מי הנהר מאמצעות טקטיקת הצפה האזור ומספקת מי שתייה ומים להשקיה לתושבים.', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 1, 'paragraph', 'אסואן היא העיר הדרומית ביותר במצרים ובירת המחוז הנושא את אותו שם. אוכלוסיית העיר כוללת 379,224 בני אדם. יחד עם חברת טיולי העולם העתיק, תוכלו להנות ממגוון יעדים היסטוריים ומודרניים כאחד ולטעום מאפשרויות רבות העומדות בפניכם בטיול למצריים המרהיבה. אנו נדאג לחוויה בלתי נשכחת והנאה בלתי פוסקת.', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 2, 'paragraph', 'היכן ניתן לסייר בסכר אסואן?', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 3, 'paragraph', 'אסואן היא עיר יפה מאוד ועתיקה שמציעה מגוון של אתרים היסטוריים. אם אתם מעוניינים לבקר ולחוות את מצרים העתיקה, אתם יכולים לראות מקדשי פילה, קום אומבו ואדפו, שנבנו לכבוד האלים המצריים, מחצבות האובליסקים, שמשם הובאו אבני הבניין הענקיות למקדשים.', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 4, 'paragraph', 'בנוסף בסכר אסואן ניתן לסייר במגוון מרכים למבקרים, מוזיאונים, אתרים היסטוריים, מוזיאונים ייחודיים, אתרי עתיקות, שווקי פשפשים ושווקי רחוב, כנסיות וקתדרלות, מסעדות ודוכני אוכל מקומיים ‪ונקודות עניין וציוני דרך נוספות להעשרת הטיול הייחודי למצרים', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 5, 'paragraph', 'האתרים החשובים ביותר לבקר בהם?', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 6, 'paragraph', 'מכיוון שעיר אסואן עשירה באתרים היסטוריים ישנם כמה אתרים מאוד חשובים בהיסטוריה המצרים אשר מומלץ לבקר בהם, והם:', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 7, 'list', null, null, '[]', '[]', false, '[{"text":"מקדשי אבו סימבל- אלה הם שני מקדשים מרשימים שנבנו על ידי פרעה רמסס השני במאה ה-13 לפני הספירה.","links":[],"children":[]},{"text":"מחצבות האובליסקים- אלה הן מחצבות של אבני גרניט שהשתמשו בהן המצריים לבניית אובליסקים.","links":[],"children":[]},{"text":"מוזיאון הנובי. זהו מוזיאון שמראה את התרבות, את ההיסטוריה, ואת האמנות של העם הנוּבּי, שחי בדרום מצרים ובשער.","links":[],"children":[]}]', null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 8, 'paragraph', 'יעדים פופולריים ביותר במצרים לבקר בהם', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 9, 'paragraph', 'אנו בטיולי העולם העתיק דואגים להביא לכם את היעדים החמים ביותר. בין היעדים הפופולריים ישנם כמה מומלצים במיוחד, כמו:', null, '[]', '[]', null, null, null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 10, 'list', null, null, '[]', '[]', false, '[{"text":"טיול לפירמידות המפורסמות אשר הפכו לאיקונות תרבותיות של המורשת האנושית.","links":[],"children":[]},{"text":"טיול לאלכסנדריה העיר החשובה ביותר בהיסטוריה המצרית והשנייה בגודלה.","links":[],"children":[]},{"text":"טיול לקהיר המרהיבה שהיא עיר הבירה של מצרים.","links":[],"children":[]}]', null, null),
('page-56dcafb5-3628-4c18-953c-02b0deb8adc9', 11, 'paragraph', 'אם אתם מחובבי היסטוריה העתיקה, הבטיחו לעצמכם את מקומכם כבר בטיול הקרוב יחד איתנו.', null, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 0, 'heading', 'חמש דברים שלא ידעתם על יוון העתיקה', 3, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 1, 'paragraph', 'יוון העתיקה היא מקור השראה לתרבות המערבית, עם תרומות רבות בתחומים מגוונים כמו פילוסופיה, מדע, אמנות וספורט. אך מעבר לעובדות הידועות, ישנם פרטים פחות מוכרים ומרתקים על התרבות והחיים ביוון העתיקה. הנה חמש עובדות כאלו:', null, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 2, 'heading', '1. בתי ספר לאסטרונומיה בפורוס', 4, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 3, 'paragraph', 'באי פורוס בצפון יוון פעלו בתי ספר לאסטרונומיה ומדעים מדויקים. אסטרונומים כמו היפרכוס וקלאודיוס פיתולמאיוס ערכו תצפיות אסטרונומיות ותיעדו את מיקומי הכוכבים. השיטות שפיתחו נחשבות לפורצות דרך בתחום האסטרונומיה והמתמטיקה, והשפעתן ניכרת עד היום.', null, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 4, 'heading', '2. בתי המשפט היווניים והצבעות הטין', 4, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 5, 'paragraph', 'בתי המשפט ביוון העתיקה היו שונים מאוד מאלה שאנו מכירים היום. במשפטים, אזרחים משכבות שונות השתתפו בחבר המושבעים, לעיתים היו בהם מאות אנשים. הצבעות התקיימו באמצעות “אוסטרקון” – חרסים שעליהם נכתבו שמות המועמדים לגירוש. שיטה זו נועדה להבטיח שהכוח לא ירוכז בידי אדם אחד זמן רב מדי.', null, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 6, 'heading', '3. תחרויות שירה ומוזיקה בדלפי', 4, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 7, 'paragraph', 'דלפי, הממוקמת בצפון יוון, הייתה לא רק מרכז דתי, אלא גם מקום חשוב לתחרויות שירה ומוזיקה. פסטיבל הפיתיה, שנערך לכבוד אפולו, כלל תחרויות של אמני שירה ונגינה על כלי מיתר. המתחרים היו מגיעים מכל רחבי יוון והתחרו על תהילה ופרסים יקרי ערך.', null, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 8, 'heading', '4. תפקיד הנשים בספרטה', 4, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 9, 'paragraph', 'בספרטה, עיר-מדינה בדרום יוון, היו לנשים זכויות ותפקידים שונים מאוד מאלה של נשים באתונה. נשים ספרטניות קיבלו חינוך גופני, השתתפו בתחרויות ספורט, ואפילו החזיקו ברכוש וניהלו עסקים. הן היו ידועות בכוחן ובחופש האישי שהוענק להן, תופעה יוצאת דופן בהשוואה לשאר יוון העתיקה.', null, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 10, 'heading', '5. מערכת הביוב המתקדמת של קנוסוס', 4, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 11, 'paragraph', 'קנוסוס, בירת התרבות המינואית בכרתים, הייתה בעלת מערכת ביוב מתקדמת שהקדימה את זמנה במאות שנים. הארמון של קנוסוס כלל תעלות ניקוז ותשתית שהובילה את המים המלוכלכים מחוץ לעיר. זו הייתה אחת ממערכות הביוב הראשונות בעולם, והיא שיקפה את הרמה ההנדסית הגבוהה של היוונים הקדומים.', null, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 12, 'paragraph', 'העובדות הללו מעניקות הצצה מרתקת לחיים ביוון העתיקה, מעבר למה שמוכר לכל. הן ממחישות את הגיוון התרבותי והחברתי של אותה תקופה, ואת השפעתה הנרחבת על התרבות והמדע המודרניים. צפון יוון, כמו שאר האזורים ביוון, שמר על חלק מהמורשת הזו ומציע לנו את ההזדמנות לחקור אותה מחדש.', null, '[]', '[]', null, null, null, null),
('page-1dfc1f64-9c6a-4a46-8199-47d84ad3ff19', 13, 'heading', 'על כל אלו ועוד תוכלו ללמוד בטיול המאורגן שלנו, בהדרכתו של דוקטור אייל מירון, אשר יוצא לדרך באוקטובר הקרוב

מהרו להרשם', 4, '[]', '[{"text":"מהרו להרשם","href":"/tours/northern-greece/"}]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 0, 'heading', 'חמישה דברים שלא ידעתם על סין העתיקה', 3, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 1, 'paragraph', 'סין העתיקה היא אחת מהתרבויות העתיקות והמגוונות ביותר בעולם, עם היסטוריה עשירה ותרומה נרחבת לתרבות האנושית. הנה חמישה דברים מעניינים על סין העתיקה שכנראה לא ידעתם:', null, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 2, 'heading', '1. המצוינות המדעית של דינסטיית האן', 4, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 3, 'paragraph', 'בתקופת שושלת האן (206 לפנה”ס – 220 לספירה), סין העתיקה חוותה פריחה מדעית וטכנולוגית. בתקופה זו הומצאו המצפן, נייר הזכוכית ונייר רגיל. המצאות אלו השפיעו רבות על העולם כולו. בנוסף, הסינים הקדומים עסקו באסטרונומיה ופיתחו לוחות שנה מדויקים, אשר היו מבוססים על תצפיות כוכבים מתקדמות.', null, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 4, 'heading', '2. דרך המשי והמסחר הגלובלי', 4, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 5, 'paragraph', 'דרך המשי, שנמשכה מסין עד לאירופה, הייתה אחד מנתיבי המסחר החשובים ביותר בהיסטוריה. סין העתיקה הייתה מקור לייצוא משי, תה, פורצלן ותבלינים, אשר הגיעו לשווקים מרוחקים כמו רומא והאימפריה הפרסית. המסחר בנתיב זה לא רק הביא להעצמת הכלכלה הסינית, אלא גם אפשר חילופי תרבויות, רעיונות וטכנולוגיות בין המזרח למערב.', null, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 6, 'heading', '3. חומות העיר האימפריאלית', 4, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 7, 'paragraph', 'לפני שנבנתה החומה הגדולה, סין העתיקה הייתה ידועה בחומות העיר האימפריאלית שלה. החומות הענקיות שנבנו סביב ערים חשובות כמו שיאן, בירת דינסטיית טאנג, נועדו להגן על התושבים מפני פלישות חיצוניות. חומות אלו היו מצוידות בשערים, מגדלי שמירה ומערכות מורכבות של הגנה.', null, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 8, 'heading', '4. התפקיד המרכזי של הקונפוציאניזם', 4, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 9, 'paragraph', 'הפילוסופיה הקונפוציאנית שיחקה תפקיד מרכזי בעיצוב החברה והמדינה בסין העתיקה. קונפוציוס, שחי במאה ה-6 לפנה”ס, פיתח מערכת של ערכים מוסריים ואחריות חברתית. עקרונות אלו התמקדו בכיבוד המשפחה, חינוך והגינות. הקונפוציאניזם השפיע רבות על מערכת החינוך והממשל בסין, והפך לאבן יסוד בתרבות הסינית.', null, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 10, 'heading', '5. הרפואה הסינית העתיקה', 4, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 11, 'paragraph', 'סין העתיקה התברכה במערכת רפואה מפותחת ומורכבת. הרפואה הסינית המסורתית, המבוססת על עקרונות כמו יין ויאנג, חמשת האלמנטים ואנרגיית הצ’י, התפתחה במהלך אלפי שנים. שיטות כמו דיקור סיני, צמחי מרפא וטיפולי מגע, היו חלק בלתי נפרד מהחיים בסין העתיקה ונשמרו עד היום כשיטות טיפול מסורתיות.', null, '[]', '[]', null, null, null, null),
('page-d0f02c63-5adc-429a-9207-067f632a39c3', 12, 'paragraph', 'העובדות הללו מדגימות את העושר התרבותי וההיסטורי של סין העתיקה, ומספקות הצצה למורשת העמוקה והמורכבת של אחת מהציוויליזציות הגדולות ביותר בהיסטוריה. הסיפור של סין העתיקה ממשיך לרתק וללמד אותנו רבות על התפתחות התרבות האנושית.', null, '[]', '[]', null, null, null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 0, 'paragraph', 'בין הסמלים המובהקים לתרבות מצרים העתיקה, הן הפירמידות המפורסמות בכל העולם אשר נבנו בתקופת הממלכה הקדומה ותקופת הממלכה התיכונה לפני אלפי שנים. הן בעלות היסטוריה מרהיבה אשר עדיין לא פוענחו עד הסוף. הפירמידות המפורסמות נבנו על ידי המצרים הקדמונים בגדתו המערבית של נהר הנילוס – ארץ המתים לפי אמונתם של מצרים. בתקופת השושלות המוקדמות במצרים העתיקה, היה נהוג בקרב המצרים, לקבור את בעלי הממון במבנים דמויי ספסל אשר נקראו “מסטבה” שהם הקברים הקדומים.', null, '[]', '[]', null, null, null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 1, 'paragraph', 'הצוות שלנו של טיולי העולם העתיק הכינו עבורכם טיול לפירמידות לצד היסטוריה עוצרת נשימה בו תוכלו להנות מהתרבות המצרית העתיקה לצד תרבות מודרנית, קולינריה עשירה, שווקים, מופעים ועוד.', null, '[]', '[]', null, null, null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 2, 'paragraph', 'מה כולל הטיול לפירמידות?', null, '[]', '[]', null, null, null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 3, 'paragraph', 'בחברת טיולי העולם העתיק תוכלו להנות מטיול לפירמידות העתיקות אשר נמצאות באתר ארכיאולוגי בגיזה במרחק קצר מקהיר. זהו טיול עשיר במידע היסטורי וזהו חלק מרכזי בטיול למצרים.', null, '[]', '[]', null, null, null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 4, 'paragraph', 'בטיול לפירמידות תוכלו ליהנות ממראה נדיר של המבנים הייחודיים, נכנס לחדר הקבורה של פרעה חופו אשר בנה את הפירמידה הגדולה. הפירמידה הגדולה היא העתיקה שבשבעת פלאי תבל של העולם העתיק. תוכלו להתרשם בנוסף משאר הפירמידות השוכנות זו לצד זו.', null, '[]', '[]', null, null, null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 5, 'paragraph', 'יעדים במצרים', null, '[]', '[]', null, null, null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 6, 'paragraph', 'מעבר לטיול לפירמידות העתיקות, ישנם יעדים מובחרים נוספים. חברת טיולי העולם העתיק מביאים לכם את הטיולים הכי נחשקים במצרים, כמו למשל:', null, '[]', '[]', null, null, null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 7, 'list', null, null, '[]', '[]', false, '[{"text":"טיול לאלכסנדריה שהיא עיר הנמל החשובה של מצרים ובעלת היסטוריה עתיקה.","links":[],"children":[]},{"text":"טיול לסכר אסואן שהוא מערכת של שני סכרים על נהר הנילוס אשר משמשים לאגירת מי הנהר.","links":[],"children":[]},{"text":"טיול לאבו סימבל אשר שוכן באתר ארכיאולוגי שבאבו סימבל, הכולל 2 מקדשים מתקופת השושלת ה־19 במצרים העתיקה, אשר נחצבו בסלע בנוביה, ועוד יעדים מרהיבים נוספים.","links":[],"children":[]}]', null, null),
('page-d642ebf1-f724-414e-8d32-a5c213cdd9be', 8, 'paragraph', 'בחברת טיולי העולם העתיק תוכלו להנות ממגוון רחב של טיולים למצרים. בהם טיולים משולבים עם הפלגה בפינה פרטית בעל כמה ימים לאורך הנהר הנילוס, ביקורים באתרים ארכיאולוגים, מוזיאונים, שווקים מקומיים, הספרייה הגדולה, מנזרים, נשמע את סיפור גילוי קברו של פרעה תות ענח אמון. אל תחכו לרגע האחרון והבטיחו את מקומכם כבר בטיול הקרוב למצרים המרהיבה.', null, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 0, 'heading', 'אתונה – בירת יוון והלב הפועם של התרבות המערבית', 3, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 1, 'paragraph', 'אתונה, בירתה של יוון, היא עיר המשלבת באופן יוצא דופן בין העבר המפואר לעידן המודרני. טיול לאתונה הוא מסע מרתק החושף את המבקרים לתרבות עשירה, היסטוריה עתיקת יומין ואורח חיים מודרני ותוסס. אתונה היא עיר מגוונת המשקפת את השפעתה של התרבות היוונית הקלאסית לצד נגיעות אירופאיות וים-תיכוניות. זוהי עיר הומה המונה כ-3.1 מיליון תושבים, והיא אחת הערים המסעירות והמגוונות באירופה.', null, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 2, 'heading', 'אתרים חשובים בעיר אתונה', 4, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 3, 'paragraph', 'טיול לאתונה אינו סתם טיול רגיל, אלא מסע אל העבר המפואר של יוון העתיקה. בעיר אתונה ישנם כמה אתרים מאוד חשובים בהיסטוריה היוונית ומהווים חלק בלתי נפרד ממנה, והם:', null, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 4, 'list', null, null, '[]', '[]', false, '[{"text":"הפרתנון: המקדש הגדול המוקדש לאלה אתנה, ממוקם על גבעת האקרופוליס ומשקיף על העיר.","links":[],"children":[]},{"text":"המוזיאון הלאומי לארכאולוגיה: בו נמצא אוסף הפריטים הגדול ביותר מיוון העתיקה.","links":[],"children":[]},{"text":"אגורה העתיקה: השוק המרכזי של אתונה העתיקה, שהיה מרכז החיים הציבוריים, הפוליטיים והמסחריים.","links":[],"children":[]},{"text":"פלאקה: השכונה העתיקה של אתונה, עם רחובות צרים ומלאי חנויות, מסעדות ובתי קפה מסורתיים.","links":[],"children":[]},{"text":"הר ליקאביטוס: הר הצופה על כל העיר, אליו ניתן לעלות ברכבל וליהנות מתצפית מרהיבה.","links":[],"children":[]}]', null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 5, 'heading', 'סיורים ייחודיים באתונה', 4, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 6, 'paragraph', 'בנוסף לאתרים ההיסטוריים, באתונה ניתן ליהנות מסיורים בשכונות מיוחדות ויוצאות דופן, כמו שכונות פאנקראטי וקולונאקי, המשלבות בין היסטוריה לעולם המודרני עם חנויות אופנה, גלריות אמנות ומסעדות יוקרה.', null, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 7, 'paragraph', 'אנו בחברת טיולי העולם העתיק עושים את הכול על מנת להביא לכם את הטיולים הכי שווים ועשירים בחוויות ומקומות יוצאי דופן, אשר משלבים בתוכם המון אלמנטים ואטרקציות לצד תרבות מגוונת והיסטוריה ייחודית. בטיולים שלנו תטעמו מכל דבר ומכל פינה יוונית, כך שלא תצאו מאיתנו ללא מזכרות לכל החיים.', null, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 8, 'paragraph', 'בחברת טיולי העולם העתיק תוכלו להנות מטיולים ליעדים שונים ביוון כמו:', null, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 9, 'list', null, null, '[]', '[]', false, '[{"text":"טיול לדלפי: האתר הארכאולוגי המפורסם שבו שכן האורקל של דלפי.","links":[],"children":[]},{"text":"טיול למטאורה: מנזרים מדהימים הבנויים על צוקים גבוהים.","links":[],"children":[]},{"text":"טיול לסנטוריני: אחד האיים היפים ביותר בעולם, עם נופים עוצרי נשימה.","links":[],"children":[]},{"text":"טיול לאולימפיה: מקום הולדתם של המשחקים האולימפיים.","links":[],"children":[]}]', null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 10, 'paragraph', 'אל תחמיצו את ההזדמנות לחוות חוויה בלתי נשכחת, והבטיחו את מקומכם כבר בטיול הקרוב לאחד היעדים הפופולריים ביוון המרהיבה.', null, '[]', '[]', null, null, null, null),
('page-10d00229-15ad-48b7-9c9d-7bb2bac24a7a', 11, 'paragraph', 'להרשמה לחצו כאן', null, '[]', '[{"text":"להרשמה לחצו כאן","href":"/tours/"}]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 0, 'heading', 'בייג’ינג – בירת סין והלב הפועם של התרבות הסינית', 3, '[]', '[]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 1, 'paragraph', 'בייג’ינג, בירתה של סין, היא עיר המשלבת בין ההיסטוריה העתיקה לבין הקדמה והמודרניזציה. טיול לבייג’ינג הוא מסע מרתק החושף את המבקרים לתרבות עשירה והיסטוריה מרשימה, לצד חוויות מודרניות וחדשניות. בייג’ינג היא עיר מגוונת המשלבת בין מסורת סינית עתיקה להשפעות מערביות מודרניות. זוהי עיר צפופה המונה כ-21 מיליון תושבים, והיא אחת הערים הגדולות והמרתקות בעולם.', null, '[]', '[]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 2, 'heading', 'אתרים חשובים בעיר בייג’ינג', 4, '[]', '[]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 3, 'paragraph', 'טיול לבייג’ינג אינו סתם טיול רגיל, אלא מסע אל העבר המפואר של סין העתיקה. בעיר בייג’ינג ישנם כמה אתרים מאוד חשובים בהיסטוריה הסינית ומהווים חלק בלתי נפרד ממנה, והם:', null, '[]', '[]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 4, 'list', null, null, '[]', '[]', false, '[{"text":"העיר האסורה: מתחם הארמונות הגדול ביותר בעולם, שהיה מקום מושבם של קיסרי סין במשך מאות שנים.","links":[],"children":[]},{"text":"חומת סין הגדולה: אחד משבעת פלאי תבל, חומת ההגנה הארוכה ביותר בעולם.","links":[],"children":[]},{"text":"מקדש השמיים: מתחם דתי מרהיב שבו נערכו טקסי פולחן חשובים בקיסרות הסינית.","links":[],"children":[]},{"text":"כיכר טיין-אן-מן: הכיכר הציבורית הגדולה בעולם, מרכז היסטורי ופוליטי חשוב.","links":[],"children":[]},{"text":"שוק הפנינים: שוק מסורתי שבו ניתן למצוא תכשיטים, בגדים ומזכרות ייחודיות.","links":[],"children":[]}]', null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 5, 'heading', 'סיורים ייחודיים בבייג’ינג', 4, '[]', '[]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 6, 'paragraph', 'בנוסף לאתרים ההיסטוריים, בבייג’ינג ניתן ליהנות מסיורים בשכונות מיוחדות ויוצאות דופן, כמו שכונת 798 האומנותית ושכונת חוטונג, המשלבת בין היסטוריה לסצנה מודרנית עם גלריות, חנויות בוטיק ומסעדות מסורתיות.', null, '[]', '[]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 7, 'paragraph', 'אנו בחברת טיולי העולם העתיק עושים את הכול על מנת להביא לכם את הטיולים הכי שווים ועשירים בחוויות ומקומות יוצאי דופן, אשר משלבים בתוכם המון אלמנטים ואטרקציות לצד תרבות מגוונת והיסטוריה ייחודית. בטיולים שלנו תטעמו מכל דבר ומכל פינה סינית, כך שלא תצאו מאיתנו ללא מזכרות לכל החיים.', null, '[]', '[]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 8, 'paragraph', 'בחברת טיולי העולם העתיק תוכלו להנות מטיולים ליעדים שונים בסין כמו:', null, '[]', '[]', null, null, null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 9, 'list', null, null, '[]', '[]', false, '[{"text":"טיול לשנגחאי: העיר הגדולה ביותר בסין, עם נוף אורבני מרהיב ושפע של אתרים היסטוריים ומודרניים.","links":[],"children":[]},{"text":"טיול לגווילין: עיר קסומה עם נופי קרסט מדהימים וטרסות אורז עם משמעות תרבותית עמוקה.","links":[],"children":[]},{"text":"טיול לשיאן: עיר עתיקה המפורסמת בזכות צבא הטרקוטה והופעות מרהיבות.","links":[],"children":[]}]', null, null),
('page-a8b24e49-16c5-4b84-a519-0de512ec4252', 10, 'paragraph', 'אל תחמיצו את ההזדמנות לחוות חוויה בלתי נשכחת, והבטיחו את מקומכם כבר בטיול הקרוב לאחד היעדים הפופולריים בסין המדהימה.', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 0, 'paragraph', 'סין היא מדינה עוצרת נשימה – אדירה בגודלה, עשירה בתרבות, מגוונת בנופים, ומפתיעה בכל צעד. עם היסטוריה של למעלה מ-3,500 שנה, שפה מוסיקלית וייחודית, דתות ופילוסופיות ששינו את פני המזרח, טיול מאורגן לסין הוא הרבה מעבר לחופשה – זהו מסע לעולם אחר, מרתק ועמוק.', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 1, 'paragraph', 'למה לבחור דווקא בטיול מאורגן לסין?', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 2, 'paragraph', 'סין היא מדינה מורכבת לתייר העצמאי – השפה, התחבורה, הריחוק התרבותי והמרחקים הארוכים בין היעדים, עלולים להקשות על חוויית הטיול.

טיול מאורגן לסין מעניק שקט נפשי, תכנון מוקפד, וחשוב מכל – מדריך דובר עברית מומחה לסין המלווה את הקבוצה לאורך כל הדרך, מעניק הקשרים תרבותיים והיסטוריים, ומבטיח ניצול מיטבי של הזמן והמשאבים.בנוסף בטיולי העולם העתיק ישנו מלווה ישראלי היוצא עם הקבוצה מהארץ וכמובן גם מדריך סיני דובר אנגלית', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 3, 'paragraph', 'אתרים שאסור לפספס בסין', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 4, 'paragraph', 'טיול מאורגן לסין כולל לרוב את האתרים הבולטים והמרהיבים ביותר במדינה:', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 5, 'list', null, null, '[]', '[]', false, '[{"text":"העיר האסורה בבייג’ינג – מתחם הקיסרים הגדול ביותר בעולם.כיכר טיאננמאן המפורסמת אשר בה הורכזה הרפובליקה העממית של סין להבדיל מהרפובליקה של סין אשר בטיוואן.","links":[],"children":[]},{"text":"גבעת הפיחם","links":[],"children":[]},{"text":"מקדש קונפוציוס","links":[],"children":[]},{"text":"מקדש הלאמה","links":[],"children":[]},{"text":"מקדש הפעמון","links":[],"children":[]},{"text":"החוטונג -שכונה סינית לשימור אשר מחירי הנדל”ן שם גבוהים מתל אביב","links":[],"children":[]},{"text":"החומה הסינית הגדולה – פלא אדריכלי באורך אלפי קילומטרים.","links":[],"children":[]},{"text":"צבא חיילי הטרהקוטה בשיאן – אתר קבורה עצום של קיסרי סין משושלת מינג טראסות האורז של לונג’י – נוף חקלאי מרהיב ומסורת חיה שמורת טבע מיוחדת במינה.","links":[],"children":[]},{"text":"גשר הזכוכית אשר תוכנן על ידי האדריכל הישראלי חיים דותן.","links":[],"children":[]},{"text":"אחד מהאתרים המרהיבים והמרגשים בעולם.כמובן גם הר טיאנמאן המפורסם בזכות הסרט אווטאר ומערת השמים","links":[],"children":[]},{"text":"העיר שאנגחאי – “תל אביב של סין” – שילוב מושלם בין עבר קולוניאלי למודרניות עוצרת נשימה.","links":[],"children":[]},{"text":"בית הכנסת והסיפור המופלא של יהדות סין","links":[],"children":[]}]', null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 6, 'paragraph', 'במסלול איכותי, משלבים גם אתרי טבע נדירים, מופעי תרבות מקומיים, מקדשים, מסגדים, פינות חמד לא מוכרות ושווקים ססגוניים.', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 7, 'paragraph', 'מדריך מקצועי בעל ידע מעמיק בתחום הקשוב למטיילים עם רגישות והבנת הצרכים המעביר את היידע באופן מאפנט ומסקרן זה אחד הדברים החשובים ביותר בטיול מאורגן לסין עם טיולי העולם העתיק', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 8, 'paragraph', 'אחד המרכיבים החשובים ביותר בטיול מאורגן לסין הוא המדריך. מדריך טוב מביא ידע, ניסיון, גישה אישית, חיבור לתרבות המקומית, ואהבה אמיתית ליעד ולמטיילים.

הדרכה בעברית, בגובה העיניים, משלבת בין עובדות היסטוריות לסיפורים אנושיים – והופכת כל אתר לחוויה בלתי נשכחת.בנוסף לכך הליוי הצמוד של מורה דרך ישראלי נוסף מאפשרת הרבה נוחות בטיול', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 9, 'paragraph', 'טיול עומק ולא מרוץ אטרקציות', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 10, 'paragraph', 'טיול רגוע, עם קצב נעים, תוכן מעשיר והיכרות מעמיקה עם היעד. טיול מאורגן לסין בקבוצה קטנה מאפשר להתרשם מהעולם העתיק והמודרני הסיני וכן לפגוש בשבטים המקומיים ולתהות ולהבין את האופן בו הם חיים, ליהנות מארוחות מקומיות איכותיות, לטייל בנופים קסומים ולהבין את סין מבפנים – לא רק מהחלון של האוטובוס.', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 11, 'paragraph', 'קולינריה סינית – טעמים שלא שוכחים', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 12, 'paragraph', 'אי אפשר לדבר על סין בלי להזכיר את האוכל:

ממרקי נודלס טריים, דרך כיסונים מסורתיים, ועד מטעמים מקומיים שכל אזור מתגאה בהם. בטיול מאורגן לסין תוכלו ליהנות מהחוויה הקולינרית בצורה בטוחה, מודרכת, וללא חשש – כשיש מדריך שמכיר את המקומות הנכונים.כמובן שתכירו את המאכלים הפופולריים והיחודיים לכל עיר כמו “ברווז פאקין” או “דאמפלינג” וכמובן “הוט פוט”', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 13, 'paragraph', 'בתי המלון שנבחרו הינם ברמה גבוהה מאוד וכלל הלוגיסטיקה מאוד מוקפדת מבקבוק המים המינרליים הקרים ועד האוטובוס החדיש והממוזג וכלה באוזניות שמע איכותיות', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 14, 'paragraph', 'אנו בטיולי העולם העתיק מקפידים בקוצו של יוד על כל דבר ובפרט על מנת להנעים את הזמן ולהעשיר את חויותיו של המטייל איתנו, חוויה לכל החיים וחד פעמית', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 15, 'paragraph', 'הירשמו לפני שיהיה מאוחר כי אין לדעת מה צופן לנו העתיד באיזור, אז כדאי לנצל חלון הזדמנויות קטן זה', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 16, 'paragraph', 'למי מתאים טיול מאורגן לסין?', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 17, 'list', null, null, '[]', '[]', false, '[{"text":"מטיילים בני 50+","links":[],"children":[]},{"text":"חובבי תרבות, היסטוריה ואמנות","links":[],"children":[]},{"text":"אוהבי טבע ונופים מיוחדים","links":[],"children":[]},{"text":"מי שמחפש טיול חכם, מעשיר ומעורר השראה","links":[],"children":[]},{"text":"אנשים שמעריכים הדרכה איכותית וקבוצה קטנה ואינטימית","links":[],"children":[]}]', null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 18, 'paragraph', 'לסיכום: הדרך הנכונה לחוות את סין', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 19, 'paragraph', 'טיול מאורגן לסין הוא הבחירה הנכונה למי שרוצה לחוות את אחת התרבויות העתיקות והמרתקות בעולם – בלי דאגות, עם אנשים טובים, מסלול מתוכנן היטב, מדריכים מקצועיים ואווירה בלתי נשכחת.', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 20, 'paragraph', 'אם גם אתם חולמים על טיול מאורגן לסין שכולל תוכן איכותי, מסלול עשיר, ומדריכים מרתקים – אנחנו בטיולי העולם העתיק מזמינים אתכם להצטרף למסע חווייתי שלא תשכחו.', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 21, 'paragraph', '📍 יציאה מובטחת בנובמבר 2025 | קבוצה קטנה | כולל טיסות, מלונות, אוכל, סיורים והדרכה מלאה כמובן יהיה מפגש מטיילים בירושלים לא בזום אשר נספר עוד על הטיול והפרטים הקטנים', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 22, 'paragraph', 'להתראות רוני אלה וד”ר אייל מירון טיולי העולם העתיק', null, '[]', '[]', null, null, null, null),
('page-1b9cfdf5-9ee7-4d5f-8fc8-c8bdad1a7c68', 23, 'paragraph', 'למידע נוסף על טיול מאורגן לסין: https://roniellatours.com/הטיולים-שלנו/סין-צונג-גואה/', null, '[]', '[{"text":"https://roniellatours.com/הטיולים-שלנו/סין-צונג-גואה/","href":"/tours/china-september-2027/"}]', null, null, null, null),
