('page-11b19c6d-4634-4aaf-82ce-7e1f5fb35795', 6, 'heading', 'טיולי העולם העתיק הינו עסק פרטי המנוהל על ידי מורי דרך מוסמכים מטעם משרד התיירות. אנו מארגנים טיולי בוטיק גאוגרפיים ולימודיים בארצות העולם העתיק ומעבר. בטיולנו אנו דואגים לרמה גבוהה של שירותים מקומיים ולדבר החשוב ביותר ההדרכה.', 4, '[]', '[]', null, null, null, null),
('page-11b19c6d-4634-4aaf-82ce-7e1f5fb35795', 7, 'heading', 'חשוב שההדרכה בטיול תהיה משמעותית, מעניינת ומהנה למטייל. בסמוך ולפני כל טיול אנו חוקרים שוב את האתרים בשטח מאחר וישנם שינויים, לכן אנו דואגים להיות מעודכנים ולתת למטילנו את המיטב ולנצל את זמן הטיול באופן היעיל ביותר ומבלי לבזבז זמן עקב שינויים באתרים השונים.', 4, '[]', '[]', null, null, null, null),
('page-11b19c6d-4634-4aaf-82ce-7e1f5fb35795', 8, 'heading', 'מאחר והכל מתבצע על ידינו באופן אישי אנו זמינים 24/7 לכל שאלה/ בקשה או עזרה בכל נושא.', 4, '[]', '[]', null, null, null, null),
