('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 2, 'paragraph', 'אתר שמוגדר “נגיש” אמור לספק חווית גלישה נעימה ונוחה לכולם. מדובר על אתר ידידותי, זמין 24 שעות ביממה לשימוש עבור אנשים עם מוגבלויות, לקויות ואנשים המתקשים בהפעלת המחשב והאינטרנט.', null, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 3, 'paragraph', 'אתר נגיש מאפשר לכלל הגולשים לגלוש בנוחות ובמהירות וליהנות מהתכנים והשירותים המוצעים באתר בצורה הטובה ביותר.', null, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 4, 'paragraph', 'האתר נבנה בהתאם להוראות הנגישות המופיעות ב –W3C’s Web Content Accessibility Guidelines 2.0, level AA', null, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 5, 'heading', 'שימוש בתפריט הנגישות', 2, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 6, 'paragraph', 'אנחנו משתמשים בכלי הנגשת אתרים מבית CODE IN ROL', null, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 7, 'paragraph', 'בלחיצה על הכפתור יפתח תפריט נגישות עם כלי עזר שונים:', null, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 8, 'heading', 'מה ניתן לשנות?', 3, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 9, 'list', null, null, '[]', '[]', false, '[{"text":"ניווט במקלדת","links":[],"children":[]},{"text":"ביטול הבהובים ואנימציות","links":[],"children":[]},{"text":"שינוי ניגודיות (כהה / בהירה)","links":[],"children":[]},{"text":"הגדלת טקסט","links":[],"children":[]},{"text":"הקטנת טקסט","links":[],"children":[]},{"text":"שינוי לגופן קריא יותר","links":[],"children":[]},{"text":"סימון כותרות","links":[],"children":[]},{"text":"סימון קישורים ולחצנים","links":[],"children":[]}]', null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 10, 'heading', 'מערכות הפעלה ודפדפנים', 2, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 11, 'paragraph', 'כתובת האתר והדפים השונים הקשורים לדומיין www.shimara.co.il נבדקו במערכות הפעלה Windows ו OSX בדפדפנים: אדג’, כרום ודפדפן Firefox בגרסאות האחרונות.', null, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 12, 'heading', 'דיווח על תוכן לא נגיש', 2, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 13, 'paragraph', 'אנו עושים את מירב המאמצים להציג אתר נגיש שנדרש על פי חוק, ייתכן וחלק מהדפים יהיו פחות נגישים. במידה ומצאתם עמוד שאינו נגיש נשמח אם תשלחו למנהל אחסון האתר פנייה ישירה למייל בכתובת roniellatours@gmail.com', null, '[]', '[{"text":"roniellatours@gmail.com","href":"mailto:roniellatours@gmail.com"}]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 14, 'paragraph', 'יש לציין את העמוד כולל קישור ישיר על מנת שנוכל לבדוק ברצינות את הפניה, צרו קשר ונפעל לבצע התאמות במידת הצורך לפי יכולתנו.', null, '[]', '[]', null, null, null, null),
('page-0e958bd7-b13b-4fa1-b49a-57bca790aa2f', 15, 'paragraph', 'הצהרה זאת עודכנה לאחרונה בתאריך: 7/4/24.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 0, 'heading', 'תנאי תשלום', 2, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 1, 'paragraph', 'עם ההרשמה תשלום ראשון על סך 1000 ש”ח

60 יום לפני מועד הטיול תשלום שני ל סך 4000 ש”ח

30 יום לפני מועד הטיול ייתרת כל הסכום

התשלום יבוצע בהוראת קבע או מזומן

כל תשלום יחושב לפי שער היורו מכירה מזומן בבנק הפועלים ביום התשלום', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 2, 'heading', 'תנאי ביטול', 2, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 3, 'paragraph', 'מיום ההרשמה ועד 14 יום ללא דמי ביטול ובלבד שנותרו יותר מ 60 יום למועד הטיול', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 4, 'paragraph', '45-60 יום לפני מועד הטיול דמי ביטול 1000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 5, 'paragraph', '44-30 יום לפני מועד הטיול דמי ביטול 3000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 6, 'paragraph', '29-15 יום לפני מועד הטיול דמי ביטול 5000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 7, 'paragraph', '14 יום ופחות עד מועד הטיול דמי הביטול הינם כל סכום עלות הטיול ללא החזר', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 8, 'paragraph', 'כל החזר בגין ביטול טיול יבוצע בהעברה בנקאית לחשבון ממנו התקבל התשלום', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 9, 'heading', 'תנאים ומדיניות המארגנים', 2, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 10, 'paragraph', 'תנאים אלו הינם חלק בילתי נפרד מההזמנה ומהווה חוזה בין טיולי העולם העתיק המארגנים או מי מטעמם לבין הלקוח.בעצם הרשמותו של מטייל מבטאים הסכמה מפורשת לתנאים המפורטים להלן.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 11, 'paragraph', 'טיולי העולם העתיק מזמינים שרותים שונים בחו”ל על פי הצורך לכל טיול.אנו מתחייבים לבצע הזמנת שירותים בחו”ל במיומנות ובהקפדה ייתרה.אנו נוודא לכל טיול את התנאים על מנת למנוע שיבושים ותקלות.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 12, 'paragraph', 'טיולי העולם העתיק או מי מטעמם לא יהיה אחראי לשיבושים ותקלות בלתי צפויים שאינם בשליטתה.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 13, 'paragraph', 'טיולי העולם העתיק לא תהיה אחראית לגבי ספקי השירות השונים בכל דבר ועניין לרבות חברות התעופה, המלונות,סידורי הקרקע,השייט,בתי המלון,אשרות כניסה וכדומה.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 14, 'paragraph', 'סדר ימי הטיול, האתרים,המלונות ועוד יכולים להשתנות על פי שיקולי המדריך ולטובת הנוסעים וזאת ללא הודעה מראש', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 15, 'heading', 'כוח עליון', 2, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 16, 'paragraph', 'במידה והטיול לא ייצא כמתוכנן בשל כח עליוןלרבות מזג אויר,אסון טבע,מצב בטחוני,אנו נספק אלטרנטיבה ראוייה או לחילופין זיכוי עתידי. לא יינתן החזר כספי.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 17, 'paragraph', 'במידה ויש צורך בויזה ולא יתקבלה ויזה במועד יחוייב הלקוח בדמי ביטול על פי מדיניות הביטול שלנו.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 18, 'heading', 'חיסונים ובריאות', 2, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 19, 'paragraph', 'על הלקוח מוטלת האחריות הבלעדית לוודא מול משרד הבריאות או כל גורם אחר אשר יראה לנכון את הצורך בחיסונים השונים במידת הצורךץ', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 20, 'paragraph', 'חובה לקנות ביטוח רפואי עם ההרשמות לטיול.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 21, 'paragraph', 'אנו ממליצים להרחיב את הביטוח גם לביטוח מטען וביטול טיול על פי תנאי הפוליסה בחברות השונות.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 22, 'heading', 'טיסות', 2, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 23, 'paragraph', 'יש לוודא את תנאי הכבודה בכל טיול. אנו נציין בכל טיול מה כולל וכל שמעבר למשקל הכלול או למספר המיזוודות יהיה על חשבון הלקוח.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 24, 'paragraph', 'אין אפשרות לשמור מקומות ישיבה מראש וייתכן אך שבני זוג ייושבו בכסאות נפרדים.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 25, 'paragraph', 'שינוי שם או אות לאחר ההרשמה עשוי לגרום לתוספת משמעותית בעלות כרטיס הטיסה שיחולו על הלקוח.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 26, 'paragraph', 'טיולי העולם העתיק רשאים להחליף מדריך לפי הצורך ועל פי שיקול דעתה והדבר לא יהווה עילא לביטול הטיול.', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 27, 'paragraph', 'ביצוע הטיול מותנה במינימום משתתפים במידה ולא ייצא הטיול מסיבה זאת. טיולי העולם העתיק תחזיר את כל הכספים ששולמו למעט הוצאת ויזה באם הייתה כזאת ולא תהיה כל טענה נוספת כלפי טיולי העולם העתיק או מי מטעמה', null, '[]', '[]', null, null, null, null),
('page-4c573761-052a-4365-98fe-78b021e4cf4b', 28, 'heading', 'המחיר כולל', 2, '[]', '[]', null, null, null, null),
