('page-2e63b934-ac47-4c06-9869-8a08048796bc', 15, 'list', null, null, '["block-8fea677e-2699-481e-8a30-88fb33db4d24"]', '[]', false, '[{"text":"מענה לפניות שנשלחו דרך האתר","links":[],"children":[]},{"text":"מתן שירות, ליווי, יצירת קשר וחזרה למתעניינים","links":[],"children":[]},{"text":"שליחת עדכונים, ניוזלטרים ותוכן שיווקי (בכפוף להסכמה)","links":[],"children":[]},{"text":"ניתוח ושיפור חוויית המשתמש","links":[],"children":[]},{"text":"אבחון תקלות ושיפור ביצועי האתר","links":[],"children":[]},{"text":"תפעול מערכות CRM וכלים טכנולוגיים הדרושים לעבודה","links":[],"children":[]},{"text":"עמידה בחובות על פי דין","links":[],"children":[]},{"text":"מניעת הונאות ואבטחת מידע","links":[],"children":[]}]', null, null),
('page-2e63b934-ac47-4c06-9869-8a08048796bc', 16, 'paragraph', 'החברה לא תעשה שימוש במידע למטרות אחרות ללא הסכמה מפורשת.', null, '["block-70edc9a8-5353-46c1-b3aa-4ca1f03b9085"]', '[]', null, null, null, null),
('page-2e63b934-ac47-4c06-9869-8a08048796bc', 17, 'list', null, null, '["block-e038b883-2336-489d-9c79-2a25f66e8914"]', '[]', false, '[{"text":"מסירת מידע לצדדים שלישיים","links":[],"children":[]}]', null, null),
('page-2e63b934-ac47-4c06-9869-8a08048796bc', 18, 'paragraph', 'החברה אינה מעבירה מידע אישי לצדדים שלישיים אלא במקרים הבאים:', null, '["block-056760e9-0a27-4ded-91f9-4e3deb32f821"]', '[]', null, null, null, null),
('page-2e63b934-ac47-4c06-9869-8a08048796bc', 19, 'paragraph', 'א. לצורך תפעול האתר ושירותים טכניים', null, '["block-38c4adc4-bab5-49b2-8fd9-07fa63957998"]', '[]', null, null, null, null),
