('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 0, 'heading', 'צפון יוון:', 2, '[]', '[]', null, null, null, null),
('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 1, 'heading', 'טיול עומק לארץ האלים והגיבורים
עם ד"ר אייל מירון', 2, '[]', '[]', null, null, null, null),
('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 2, 'heading', 'יוון, הלאס. מה לא נאמר עליה? ארץ האלים השובה את הדמיון…ערש הדמוקרטיה המערבית…המקום שבו התהלכו הפילוסופים סוקרטס, אפלטון ואריסטו, התרבות שבה החל המסע הארוך והמהוסס שעיצב את המדע המודרני כאשר חלוצי המדעים ניסו להקיף במחשבתם שמים וארץ.', 3, '[]', '[]', null, null, null, null),
('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 3, 'paragraph', 'להמשך קריאה »', null, '[]', '[]', null, null, null, null),
('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 4, 'heading', 'זו ארץ המקדשים הדוריים היוניים והקורינתיים מלאי ההדר והיופי, המנזרים המופלאים מעוטרי האיקונות, בתי כנסת השומרים את תהילת העבר של קהילות יהודיות, וזכרו של שלטון מוסלמי המרחף מעל.', 4, '[]', '[]', null, null, null, null),
('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 5, 'heading', 'זו ארצם של הרקלס הגיבור שעמד בנסיונות אימתניים וסופו הטרגי מהדהד עד ימינו, של פרסאוס שכרת את ראשה של מדוזה בעלת שיער הנחשים, סיפורים על אהבה קנאה וגורל אכזר שהוצגו לראשונה על במות התיאטרון היווני, דמויות אפופות יוהרה כאדיפוס האומלל וגיבורים שאפתנים כתזאוס שיצא לחפש את גיזת הזהב.', 4, '[]', '[]', null, null, null, null),
('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 6, 'heading', 'זו ארצם של המלך פיליפוס שאת אוצרותיו נראה ושל ובנו אלכסנדר מוקדון, שהשליט את מרותו גם על ארץ ישראל. זו גם ארצו של אנטיוכוס הרביעי המוכר לנו היטב מחג החנוכה.', 4, '[]', '[]', null, null, null, null),
('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 7, 'heading', 'בסיור העומק בצפון יוון נשוטט בדרכי הנוף הדרמטי, באור התכלת העזה, נחלוף במנהרות המודרניות המבתרות את ההרים הנישאים, נבקר באתרי עתיקות ובמוזיאונים, במפלי מים שוצפים, בהרים שנוצרו בתהליכים גיאולוגיים מרתקים, במצודות ענק, בפסלי הנצחה ובגשרים ציוריים. בדרכנו נלמד את סיפורה של יוון ההיסטורית לצד סיפורה של יוון המודרנית, נשתאה לנוכח תכשיטי זהב מופלאים, נלמד על קברי קדמונים מעוטרים ונחקור שרידי ערים ומקדשים המהדהדים את קולם של אנשים שחלפו ואינם עוד. נשמע על האדריכלות ואמנות הקדומה, נתוודע למכמני השפה היוונית, ונחקור את ההשפעות ההדדיות בין תרבות יוון לתרבותה של ארץ ישראל הקדומה. לצד אלה נשמע גם על החברה היוונית המודרנית והקשיים שעימם היא מתמודדת, על המוסיקה והאוכל המהווים מרכיב כה חשוב בתרבות זו ועל מה לא… וכל זאת כשמעל הכל מתנשא בהוד מלכות הר האולימפוס הטובל בעננים וממנו משקיפים בבדידותם אלי העבר שכמעט נשכחו מלב. אלים שפעם השתעשעו בגורלם של בני האדם כבובות על חוט ועתה הם עצמם נחתמו בשאגת צער בין דפיה המצהיבים של ההיסטוריה.', 4, '[]', '[]', null, null, null, null),
('page-91f21a4c-b40b-431c-a1d6-6e2e966c0929', 8, 'paragraph', 'הצצה לטיול עומק לצפון יוון עם ד"ר אייל מירון: לחצו על הסרטון', null, '[]', '[]', null, null, null, null),
