('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 46, 'paragraph', '45-60 יום לפני מועד הטיול דמי ביטול 1000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 47, 'paragraph', '44-30 יום לפני מועד הטיול דמי ביטול 3000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 48, 'paragraph', '29-15 יום לפני מועד הטיול דמי ביטול 5000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 49, 'paragraph', '14 יום ופחות עד מועד הטיול דמי הביטול הינם כל סכום עלות הטיול ללא החזר', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 50, 'paragraph', 'כל החזר בגין ביטול טיול יבוצע בהעברה בנקאית לחשבון ממנו התקבל התשלום', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 51, 'paragraph', 'תנאים ומדיניות המארגנים', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 52, 'paragraph', 'תנאים אלו הינם חלק בלתי נפרד מההזמנה ומהוים חוזה בין טיולי העולם העתיק המארגנים או מי מטעמם לבין הלקוח.בעצם הרשמותו של מטייל מבטאים הסכמה מפורשת לתנאים המפורטים להלן.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 53, 'paragraph', 'טיולי העולם העתיק מזמינים שירותים שונים בחו”ל על פי הצורך לכל טיול.אנו מתחייבים לבצע הזמנת שירותים בחו”ל במיומנות בהקפדה יתרה.אנו נוודא לכל טיול את התנאים על מנת למנוע שיבושים ותקלות.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 54, 'paragraph', 'טיולי העולם העתיק או מי מטעמם לא יהיה אחראי לשיבושים ותקלות בלתי צפויים שאינם בשליטתה.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 55, 'paragraph', 'טיולי העולם העתיק לא תהיה אחראית לגבי ספקי השירות השונים בכל דבר ועניין לרבות חברות התעופה, המלונות,סידורי הקרקע,השייט,בתי המלון,אשרות כניסה וכדומה.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 56, 'paragraph', 'סדר ימי הטיול, האתרים,המסלול, המלונות ועוד יכולים להשתנות על פי שיקולי המדריך ולטובת הנוסעים וזאת ללא הודעה מראש', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 57, 'paragraph', 'כח עליון', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 58, 'paragraph', 'במידה והטיול לא יצא כמתוכנן בשל כוח עליון לרבות מזג אויר,אסון טבע,מצב בטחוני,אנו נספק אלטרנטיבה ראוייה או לחילופין זיכוי עתידי. לא יינתן החזר כספי.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 59, 'paragraph', 'במידה ויש צורך בויזה ולא התקבלה ויזה במועד יחויב הלקוח בדמי ביטול על פי מדיניות הביטול שלנו.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 60, 'paragraph', 'חיסונים ובריאות', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 61, 'paragraph', 'על הלקוח מוטלת האחריות הבלעדית לוודא מול משרד הבריאות או כל גורם אחר אשר יראה לנכון את הצורך בחיסונים שונים במידת הצורך', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 62, 'paragraph', 'חובה לקנות ביטוח רפואי עם ההרשמות לטיול.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 63, 'paragraph', 'אנו ממליצים להרחיב את הביטוח גם לביטוח מטען וביטול טיול על פי תנאי הפוליסה בחברות השונות.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 64, 'paragraph', 'טיסות', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 65, 'paragraph', 'יש לוודא את תנאי הכבודה בכל טיול. אנו נציין בכל טיול מה כולל וכל שמעבר למשקל הכלול או למספר המזוודות יהיה על חשבון הלקוח.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 66, 'paragraph', 'אין אפשרות לשמור מקומות ישיבה מראש וייתכן אף שבני זוג יושבו בכיסאות נפרדים.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 67, 'paragraph', 'שינוי שם או אות לאחר ההרשמה עשוי לגרום לתוספת משמעותית בעלות כרטיס הטיסה שיחולו על הלקוח.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 68, 'paragraph', 'טיולי העולם העתיק רשאים להחליף מדריך לפי הצורך ועל פי שיקול דעתה והדבר לא יהווה עילה לביטול הטיול.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 69, 'paragraph', 'ביצוע הטיול מותנה במינימום משתתפים במידה ולא יצא הטיול מסיבה זאת. טיולי העולם העתיק תחזיר את כל הכספים ששולמו למעט הוצאת ויזה באם הייתה כזאת ולא תהיה כל טענה נוספת כלפי טיולי העולם העתיק או מי מטעמה', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 70, 'paragraph', 'המחיר כולל:', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 71, 'list', null, null, '[]', '[]', false, '[{"text":"טיסות ישורות","links":[],"children":[]},{"text":"טיסות פנים","links":[],"children":[]},{"text":"רכבות מהירות","links":[],"children":[]},{"text":"בתי מלון ברמת בוטיק","links":[],"children":[]},{"text":"ארוחת בוקר וערב","links":[],"children":[]},{"text":"כניסה לכל האתרים על פי התכנית","links":[],"children":[]},{"text":"אוטובוס צמוד","links":[],"children":[]},{"text":"מדריך מקצועי ובעל ידע רחב, מומחה לאיסלאם, ד״ר אייל מירון","links":[],"children":[]},{"text":"מדריך מקומי","links":[],"children":[]},{"text":"מלווה ישראלי שהינו מורה דרך מוסמך של משרד התיירות ובעל ניסיון רב","links":[],"children":[]},{"text":"קבוצה קטנה","links":[],"children":[]},{"text":"מפגש מטיילים בזום לפני הטיול","links":[],"children":[]}]', null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 72, 'paragraph', 'מה לא כלול?', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 73, 'list', null, null, '[]', '[]', false, '[{"text":"ביטוח בריאות ומטען (חובה)","links":[],"children":[]},{"text":"הוצאות אישיות","links":[],"children":[]},{"text":"כל מה שלא נכלל בתכנית הטיול","links":[],"children":[]}]', null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 74, 'heading', 'למה לטייל איתנו', 2, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 75, 'paragraph', 'טיולי העולם העתיק הינו עסק פרטי המנוהל על ידי מורה דרך מוסמכים מטעם משרד התיירות. אנו מארגנים טיולי בוטיק גאוגרפיים ולימודיים בארצות העולם העתיק ומעבר. בטיולנו אנו דואגים לרמה גבוהה של שירותים מקומיים ולדבר החשוב ביותר ההדרכה.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 76, 'paragraph', 'הדרכה בטיול יכולה להיות קרדינלית להנאה בטיול. בסמוך ולפני כל טיול אנו חוקרים שוב את האתרים בשטח כי מידיי פעם ישנם שינויים ולכן אנו דואגים להיות מעודכנים ולתת למטילנו את המיטב ולנצל את זמן הטיול באופן היעיל ביותר ומבלי לבזבז זמן עקב שינויים מבאתרים השונים.
עקב העובדה שהכל מתבצע על ידינו באופן אישי אנו זמינים 24/7 לכל שאלה/ בקשה או עזרה בכל נושא.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 77, 'paragraph', 'מאחר ואנו אשר בוחרים מאת המסלול והאתרים בפינצטה (ישנם הרבה אתרים פופולריים שקיבלו הרבה יחסי ציבור אבל בעצם אין בהם ממש) על פי שיקולנו המקצועיים ולא על פי אינטרסים כלכליים של נותני השירותים בחו”ל. הלקוח נהנה מטיול שהינו כטיול פרטי ומקבל תמורה מלאה לכספו.
כך יש באפשרותנו להיות גמישים בכל דבר ועניין בעת הצורך. גנמישות זאת הינה הכרכית בטיולים בכלל ובטיולים מאורגנים בפרט. אין אנו צריכים לקבל אישור מהנהלת החברה בארץ (כי אנו ההנהלה שנמצאת עימכם).או כל דבר בירוקרטי אחר.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 78, 'paragraph', 'אנו גם מתכנני הטיול גם המשווקים גם המדריכים וגם המלווים כך שתמיד הלקוח נמצא בקשר ישיר איתנו ללא צורך במתווכים על כל המתמע מכך.
בהדרכה אחד הדברים החשובים ביותר בטיול בפרט לאיזורים עם הסטוריה עשירה כמו יוון, איטליה,מצרים,סין חשוב שהמדריך יהיה מקצועי מומחה וגם מעביר את החומר באופן שינעם למטייל בחביבות ובנעימות עם חוש הומור ולכן אנו בוחרים את מדריכנו בקפידה ייתרה.', null, '[]', '[]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 79, 'paragraph', 'מסלול יומי', null, '[]', '[{"text":"מסלול יומי","href":"/tours/uzbekistan-sukkot-2027/#journy"}]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 80, 'paragraph', 'מחיר ותנאים', null, '[]', '[{"text":"מחיר ותנאים","href":"/tours/uzbekistan-sukkot-2027/#cost"}]', null, null, null, null),
('page-ea3b483b-a1af-4c08-a715-16a97d3b0082', 81, 'paragraph', 'צור קשר', null, '[]', '[{"text":"צור קשר","href":"/tours/uzbekistan-sukkot-2027/#lead"}]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 0, 'heading', 'אוזבקיסטן', 2, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 1, 'heading', 'אוזבקיסטן

עם המדריכים ד"ר אייל מירון ורוני אלה', 2, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 2, 'paragraph', 'אוזבקיסטן ניצבת בלב אסיה המרכזית, במרחב שבו נפגשו במשך מאות שנים תרבויות, דתות ואימפריות. כאן עברו שיירות הסוחרים של דרך המשי, כאן פעלו מלומדים, אסטרונומים ומשוררים, וכאן קמו ערים מפוארות שהפכו לסמלים של עושר, ידע ויצירה אנושית. מסגדים עטורי כיפות טורקיז, מדרסות מפוארות, שווקים צבעוניים, ארמונות של שליטים וקרוואנסראים עתיקים מספרים את סיפורה של אחת הזירות החשובות בתולדות העולם הישן.
במסע עומק זה של טיולי העולם העתיק, בהובלת ד”ר אייל מירון ובניהולה הלוגיסטי של רוני אלה, נצא להיכרות מרתקת עם נופיה, עברה ותרבותה של אוזבקיסטן. לאורך הדרך נחבר בין היסטוריה, דת, אמנות, פוליטיקה וחיי היום יום, ונלמד כיצד הפך האזור למוקד השפעה שחיבר בין סין, הודו, פרס, רוסיה והמזרח התיכון.
נבקר בארבע הערים המרכזיות של אוזבקיסטן: טשקנט, חיווה, בוכרה וסמרקנד. כל אחת מהן מייצגת פרק אחר בסיפורה של דרך המשי. בטשקנט נפגוש את אוזבקיסטן המודרנית לצד אתרי הדת והמורשת הלאומית; בחיווה נסייר בעיר עתיקה שנשתמרה כמעט בשלמותה ונראה כיצד נראו ערי המסחר של מרכז אסיה לפני מאות שנים; בבוכרה נעמיק באחד המרכזים החשובים של האסלאם ושל יהדות מרכז אסיה; ובסמרקנד נגלה את בירתה המפוארת של האימפריה הטימורית, אחת הערים האגדיות בתולדות העולם.
לאורך המסע נפגוש את סיפוריהם של שליטים, כובשים, מלומדים ומיסטיקנים. נשמע על טימור לנג שבנה אימפריה אדירה, על האסטרונום אולוג בק שהפך את סמרקנד למרכז מדעי עולמי, ועל אנשי הדת והסופיות שעיצבו את אופיו הרוחני של האזור. נבקר במאוזוליאומים, במדרסות, במסגדים ובאתרי קבורה מפוארים, ונלמד כיצד התפתחו כאן מסורות אדריכליות ייחודיות המשלבות השפעות פרסיות, טורקיות ומונגוליות.
מקום מיוחד במסע יוקדש ליהדות בוכרה, אחת הקהילות היהודיות העתיקות והמרתקות בעולם. נבקר ברובע היהודי, בבתי הכנסת ובבית העלמין היהודי, ונכיר את סיפורם של יהודי מרכז אסיה, את הקשרים שטיפחו עם ארץ ישראל ואת דרכם הייחודית לשמר את זהותם במשך דורות רבים בלב העולם המוסלמי.
בין האתרים ההיסטוריים נפגוש גם את אוזבקיסטן של ימינו. נסייר בשווקים הומים, נטעם ממטעמי המטבח המקומי, נכיר מלאכות מסורתיות, נשב בבתי תה ונחווה את הכנסת האורחים הידועה של תושבי האזור. נדון גם בתקופה הסובייטית, בתהליכי העצמאות של המדינה ובאתגרים העומדים בפני החברה האוזבקית במאה ה־21.
זהו מסע תרבותי והיסטורי מקיף, המיועד למטיילים המבקשים להבין לעומק את הסיפור שמאחורי האתרים, המבנים והנופים. מעבר ליופיין של הערים ולפאר האדריכלי שלהן, אוזבקיסטן מציעה מפגש עם מרחב אנושי והיסטורי ייחודי, שבו זיכרונותיה של דרך המשי עדיין ניכרים בכל כיכר, שוק וסמטה.
אוזבקיסטן אינה רק יעד לטיול. היא מסע אל אחת מצמתי התרבות החשובים בהיסטוריה האנושית, חוויה של גילוי, למידה והשראה, הממשיכה להדהד זמן רב גם לאחר החזרה הביתה.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 3, 'paragraph', 'הצצה לטיול לאוזבקיסטן עם ד"ר אייל מירון: לחצו על הסרטון', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 4, 'heading', 'טיול מאורגן', 3, '[]', '[]', null, null, null, null),
