('page-99086b24-3a6e-4817-b05a-9617a417b886', 41, 'paragraph', 'עם ההרשמה תשלום ראשון על סך 3000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 42, 'paragraph', '90 יום לפני מועד הטיול תשלום שני סך 4000 ש”ח', null, '[]', '[]', null, null, null, null),
