('page-99086b24-3a6e-4817-b05a-9617a417b886', 44, 'paragraph', 'התשלום יבוצע בהוראת קבע או מזומן', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 45, 'paragraph', 'כל תשלום יחושב לפי שער הדולר האמריקאי מכירה מזומן בבנק הפועלים ביום התשלום', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 46, 'paragraph', 'תנאי ביטול', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 47, 'paragraph', 'מיום ההרשמה ועד 14 יום ללא דמי ביטול ובלבד שנותרו יותר מ 60 יום למועד הטיול', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 48, 'paragraph', '45-60 יום לפני מועד הטיול דמי ביטול 1000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 49, 'paragraph', '44-30 יום לפני מועד הטיול דמי ביטול 3000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 50, 'paragraph', '29-15 יום לפני מועד הטיול דמי ביטול 5000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 51, 'paragraph', '14 יום ופחות עד מועד הטיול דמי הביטול הינם כל סכום עלות הטיול ללא החזר', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 52, 'paragraph', 'כל החזר בגין ביטול טיול יבוצע בהעברה בנקאית לחשבון ממנו התקבל התשלום', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 53, 'paragraph', 'תנאים ומדיניות המארגנים', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 54, 'paragraph', 'תנאים אלו הינם חלק בלתי נפרד מההזמנה ומהוים חוזה בין טיולי העולם העתיק המארגנים או מי מטעמם לבין הלקוח.בעצם הרשמותו של מטייל מבטאים הסכמה מפורשת לתנאים המפורטים להלן.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 55, 'paragraph', 'טיולי העולם העתיק מזמינים שירותים שונים בחו”ל על פי הצורך לכל טיול.אנו מתחייבים לבצע הזמנת שירותים בחו”ל במיומנות בהקפדה יתרה.אנו נוודא לכל טיול את התנאים על מנת למנוע שיבושים ותקלות.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 56, 'paragraph', 'טיולי העולם העתיק או מי מטעמם לא יהיה אחראי לשיבושים ותקלות בלתי צפויים שאינם בשליטתה.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 57, 'paragraph', 'טיולי העולם העתיק לא תהיה אחראית לגבי ספקי השירות השונים בכל דבר ועניין לרבות חברות התעופה, המלונות,סידורי הקרקע,השייט,בתי המלון,אשרות כניסה וכדומה.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 58, 'paragraph', 'סדר ימי הטיול, האתרים,המסלול, המלונות ועוד יכולים להשתנות על פי שיקולי המדריך ולטובת הנוסעים וזאת ללא הודעה מראש', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 59, 'paragraph', 'כח עליון', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 60, 'paragraph', 'במידה והטיול לא יצא כמתוכנן בשל כוח עליון לרבות מזג אויר,אסון טבע,מצב בטחוני,אנו נספק אלטרנטיבה ראוייה או לחילופין זיכוי עתידי. לא יינתן החזר כספי.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 61, 'paragraph', 'במידה ויש צורך בויזה ולא התקבלה ויזה במועד יחויב הלקוח בדמי ביטול על פי מדיניות הביטול שלנו.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 62, 'paragraph', 'חיסונים ובריאות', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 63, 'paragraph', 'על הלקוח מוטלת האחריות הבלעדית לוודא מול משרד הבריאות או כל גורם אחר אשר יראה לנכון את הצורך בחיסונים שונים במידת הצורך', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 64, 'paragraph', 'חובה לקנות ביטוח רפואי עם ההרשמות לטיול.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 65, 'paragraph', 'אנו ממליצים להרחיב את הביטוח גם לביטוח מטען וביטול טיול על פי תנאי הפוליסה בחברות השונות.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 66, 'paragraph', 'טיסות', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 67, 'paragraph', 'יש לוודא את תנאי הכבודה בכל טיול. אנו נציין בכל טיול מה כולל וכל שמעבר למשקל הכלול או למספר המזוודות יהיה על חשבון הלקוח.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 68, 'paragraph', 'אין אפשרות לשמור מקומות ישיבה מראש וייתכן אף שבני זוג יושבו בכיסאות נפרדים.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 69, 'paragraph', 'שינוי שם או אות לאחר ההרשמה עשוי לגרום לתוספת משמעותית בעלות כרטיס הטיסה שיחולו על הלקוח.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 70, 'paragraph', 'טיולי העולם העתיק רשאים להחליף מדריך לפי הצורך ועל פי שיקול דעתה והדבר לא יהווה עילה לביטול הטיול.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 71, 'paragraph', 'ביצוע הטיול מותנה במינימום משתתפים במידה ולא יצא הטיול מסיבה זאת. טיולי העולם העתיק תחזיר את כל הכספים ששולמו למעט הוצאת ויזה באם הייתה כזאת ולא תהיה כל טענה נוספת כלפי טיולי העולם העתיק או מי מטעמה', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 72, 'paragraph', 'המחיר כולל:', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 73, 'list', null, null, '[]', '[]', false, '[{"text":"טיסות ישורות","links":[],"children":[]},{"text":"טיסות פנים","links":[],"children":[]},{"text":"רכבות מהירות","links":[],"children":[]},{"text":"בתי מלון ברמת בוטיק","links":[],"children":[]},{"text":"ארוחת בוקר וערב","links":[],"children":[]},{"text":"כניסה לכל האתרים על פי התכנית","links":[],"children":[]},{"text":"אוטובוס צמוד","links":[],"children":[]},{"text":"מדריך מקצועי ובעל ידע רחב, מומחה לאיסלאם, ד״ר אייל מירון","links":[],"children":[]},{"text":"מדריך מקומי","links":[],"children":[]},{"text":"מלווה ישראלי שהינו מורה דרך מוסמך של משרד התיירות ובעל ניסיון רב","links":[],"children":[]},{"text":"קבוצה קטנה","links":[],"children":[]},{"text":"מפגש מטיילים בזום לפני הטיול","links":[],"children":[]}]', null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 74, 'paragraph', 'מה לא כלול?', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 75, 'list', null, null, '[]', '[]', false, '[{"text":"ביטוח בריאות ומטען (חובה)","links":[],"children":[]},{"text":"הוצאות אישיות","links":[],"children":[]},{"text":"כל מה שלא נכלל בתכנית הטיול","links":[],"children":[]}]', null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 76, 'heading', 'למה לטייל איתנו', 2, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 77, 'paragraph', 'טיולי העולם העתיק הינו עסק פרטי המנוהל על ידי מורה דרך מוסמכים מטעם משרד התיירות. אנו מארגנים טיולי בוטיק גאוגרפיים ולימודיים בארצות העולם העתיק ומעבר. בטיולנו אנו דואגים לרמה גבוהה של שירותים מקומיים ולדבר החשוב ביותר ההדרכה.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 78, 'paragraph', 'הדרכה בטיול יכולה להיות קרדינלית להנאה בטיול. בסמוך ולפני כל טיול אנו חוקרים שוב את האתרים בשטח כי מידיי פעם ישנם שינויים ולכן אנו דואגים להיות מעודכנים ולתת למטילנו את המיטב ולנצל את זמן הטיול באופן היעיל ביותר ומבלי לבזבז זמן עקב שינויים מבאתרים השונים.
עקב העובדה שהכל מתבצע על ידינו באופן אישי אנו זמינים 24/7 לכל שאלה/ בקשה או עזרה בכל נושא.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 79, 'paragraph', 'מאחר ואנו אשר בוחרים מאת המסלול והאתרים בפינצטה (ישנם הרבה אתרים פופולריים שקיבלו הרבה יחסי ציבור אבל בעצם אין בהם ממש) על פי שיקולנו המקצועיים ולא על פי אינטרסים כלכליים של נותני השירותים בחו”ל. הלקוח נהנה מטיול שהינו כטיול פרטי ומקבל תמורה מלאה לכספו.
כך יש באפשרותנו להיות גמישים בכל דבר ועניין בעת הצורך. גנמישות זאת הינה הכרכית בטיולים בכלל ובטיולים מאורגנים בפרט. אין אנו צריכים לקבל אישור מהנהלת החברה בארץ (כי אנו ההנהלה שנמצאת עימכם).או כל דבר בירוקרטי אחר.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 80, 'paragraph', 'אנו גם מתכנני הטיול גם המשווקים גם המדריכים וגם המלווים כך שתמיד הלקוח נמצא בקשר ישיר איתנו ללא צורך במתווכים על כל המתמע מכך.
בהדרכה אחד הדברים החשובים ביותר בטיול בפרט לאיזורים עם הסטוריה עשירה כמו יוון, איטליה,מצרים,סין חשוב שהמדריך יהיה מקצועי מומחה וגם מעביר את החומר באופן שינעם למטייל בחביבות ובנעימות עם חוש הומור ולכן אנו בוחרים את מדריכנו בקפידה ייתרה.', null, '[]', '[]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 81, 'paragraph', 'מסלול יומי', null, '[]', '[{"text":"מסלול יומי","href":"/tours/uzbekistan-march-2027/#journy"}]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 82, 'paragraph', 'מחיר ותנאים', null, '[]', '[{"text":"מחיר ותנאים","href":"/tours/uzbekistan-march-2027/#cost"}]', null, null, null, null),
('page-99086b24-3a6e-4817-b05a-9617a417b886', 83, 'paragraph', 'צור קשר', null, '[]', '[{"text":"צור קשר","href":"/tours/uzbekistan-march-2027/#lead"}]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 0, 'heading', 'אוזבקיסטן', 2, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 1, 'heading', 'עם המדריכה ד״ר רחלי קרייסברג', 2, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 2, 'paragraph', 'אוזבקיסטן, בלב אסיה המרכזית,הייתה במשך מאות שנים צומת דרכים של תרבויות, דתות ואימפריות לאורך דרך המשי. עריה המפוארות, מסגדיה עטורי כיפות הטורקיז והשוקים הססגוניים שלה מספרים את סיפורה של אחת הזירות החשובות בתולדות העולם הישן.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 3, 'paragraph', 'במסע עומק של טיולי העולם העתיק, בהדרכת רוני אלה וד”ר רחלי קרייסברג, נכיר את ההיסטוריה, התרבות והמורשת של אוזבקיסטן. נבקר בטשקנט, בוכרה וסמרקנד, ונגלה כיצד הפך האזור לגשר בין סין, הודו, פרס והמזרח התיכון.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 4, 'paragraph', 'לאורך הדרך נפגוש את סיפוריהם של טימור לנג, אולוג בק וגדולי המלומדים של מרכז אסיה, נסייר במדרסות, מסגדים ומאוזוליאומים מרהיבים, ונעמיק במורשתה של יהדות בוכרה, מן הקהילות היהודיות העתיקות בעולם.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 5, 'paragraph', 'זהו מסע תרבותי והיסטורי מרתק אל לבה של דרך המשי, בין ערים אגדיות, מורשת מפוארת ומפגש בלתי אמצעי עם אחת התרבויות המרתקות באסיה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 6, 'paragraph', 'הצצה לטיול לאוזבקיסטן עם ד"ר אייל מירון: לחצו על הסרטון', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 7, 'heading', 'טיול מאורגן', 3, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 8, 'list', null, null, '[]', '[]', false, '[{"text":"אוזבקיסטן","links":[],"children":[]},{"text":"9 ימים","links":[],"children":[]},{"text":"עם המדריכה: ד״ר רחלי קרייסברג","links":[],"children":[]}]', null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 9, 'list', null, null, '[]', '[]', false, '[{"text":"","links":[],"children":[]}]', null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 10, 'heading', 'המדריכים שלנו', 4, '[]', '[{"text":"המדריכים שלנו","href":"/guides/"}]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 11, 'paragraph', 'מסלול הטיול', null, '["journy"]', '[{"text":"מסלול הטיול","href":"/tours/uzbekistan-april-2027/#journy"}]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 12, 'paragraph', 'תנאים ועלויות', null, '[]', '[{"text":"תנאים ועלויות","href":"/tours/uzbekistan-april-2027/#cost"}]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 13, 'paragraph', 'רוצים שנחזור אליכם?', null, '[]', '[{"text":"רוצים שנחזור אליכם?","href":"/tours/uzbekistan-april-2027/#lead"}]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 14, 'heading', 'מסלול הטיול', 2, '[]', '[{"text":"מסלול הטיול","href":"/tours/uzbekistan-april-2027/#journy"}]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 15, 'heading', 'יום 1 | תל אביב – טשקנט', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 16, 'paragraph', 'נטוס מתל אביב לטשקנט, בירת אוזבקיסטן. לאחר הנחיתה נעבור למלון להתארגנות ולמנוחה לקראת המסע.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 17, 'heading', 'יום 2 | טשקנט – בין מסורת למודרניות', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 18, 'paragraph', 'נקדיש את היום להיכרות עם עיר המשלבת עבר עשיר לצד תנופת פיתוח מודרנית. נבקר במרכז הציוויליזציה האסלאמית החדש ונכיר את תרומתם של חכמי מרכז אסיה להתפתחות המדע, הפילוסופיה והתרבות בעולם האסלאמי. נמשיך למתחם חזרתי אימאם ונתרשם מהאדריכלות ומאוצרות התרבות.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 19, 'paragraph', 'בבזאר צ׳ורסו נפגוש את חיי היומיום, דוכני התבלינים, הפירות והמאפים. בהמשך נבקר בכיכר העצמאות, באתרי הזיכרון המרכזיים ובתחנות המטרו המעוצבות.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 20, 'heading', 'יום 3 | חיווה — בין חומות דרך המשי', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 21, 'paragraph', 'נגיע לחיווה ונצא להכיר את איצ׳אן קלה, העיר הפנימית המוקפת חומה, שהוכרזה אתר מורשת עולמית של אונסק״ו. נסייר בסמטאותיה ובין מדרסות, מסגדים ומבנים היסטוריים, ונכיר את סיפורה של חיווה כתחנה חשובה בדרכי השיירות של מרכז אסיה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 22, 'paragraph', 'נתוודע למסורת הבנייה והאומנות של חורזם ולאווירה המיוחדת של העיר העתיקה. פרטי ההגעה מטשקנט לחיווה יעודכנו לאחר אישור סידורי הנסיעה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 23, 'heading', 'יום 4 | מחיווה לבוכרה — נסיעה במדבר', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 24, 'paragraph', 'נצא מחיווה ליום נסיעה במדבר לעבר בוכרה. לאורך הדרך נלווה את הנוף המדברי בסיפורן של השיירות, נאות המדבר ונתיבי המסחר שחיברו בין ערי מרכז אסיה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 25, 'paragraph', 'זהו יום המוקדש למעבר בין הערים, עם עצירות בדרך בהתאם לתנאי הנסיעה. עם ההגעה לבוכרה נעבור למלון להתארגנות ולמנוחה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 26, 'heading', 'יום 5 | בוכרה — העיר הקדושה ויהדות בוכרה', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 27, 'paragraph', 'נקדיש את היום לבוכרה, עיר של מלומדים, סוחרים ואנשי דת. נסייר ברובע היהודי ובאתרים הקשורים לקהילת יהדות בוכרה, ונכיר את מורשתה ואת מקומה בחיי האזור.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 28, 'paragraph', 'נבקר במאוזוליאום איסמעיל סמאני, במצודת ארק ובמתחם לאבי האוז. נמשיך בין המדרסות, המסגדים והשווקים המקורים של העיר העתיקה, ונכיר את בוכרה כמרכז של מסחר, דת ולימוד לאורך דרך המשי.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 29, 'heading', 'יום 6 | מבוכרה לסמרקנד', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 30, 'paragraph', 'ניפרד מבוכרה וניסע לסמרקנד, מן הערים המזוהות ביותר עם דרך המשי. עם ההגעה נבקר במאוזוליאום גור אמיר, מקום קבורתו של טימור לנג, השליט שהפך את העיר לבירת אימפריה אדירה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 31, 'paragraph', 'בהמשך נבקר במתחם שאה־י־זינדה, אחד ממכלולי הקבורה והאמנות האסלאמית המרשימים במרכז אסיה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 32, 'heading', 'יום 7 | סמרקנד — פנינת דרך המשי', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 33, 'paragraph', 'נקדיש יום שלם לעיר. נבקר בכיכר רג׳יסטאן, המוקפת במדרסות מפוארות, ונמשיך למסגד ביבי חאנום ולשווקי העיר העתיקה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 34, 'paragraph', 'נלמד על תרומתה של סמרקנד למדע ולאסטרונומיה, ונכיר את מפעלו של אולוג בג ואת סיפורם של חוקרי השמים במרכז אסיה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 35, 'heading', 'יום 8 | מסמרקנד לטשקנט', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 36, 'paragraph', 'ניסע מסמרקנד בחזרה לטשקנט. עם ההגעה נעבור למלון, נסכם את חוויות המסע ונתארגן לקראת טיסת החזרה לישראל למחרת.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 37, 'heading', 'יום 9 | טשקנט – תל אביב', 4, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 38, 'paragraph', 'נצא לשדה התעופה בטשקנט בהתאם לשעת הטיסה ונשוב לישראל. נסיים מסע בן תשעה ימים בעקבות ערי דרך המשי, חיווה המוקפת חומה, נופי המדבר, האדריכלות האסלאמית ומורשת יהודית עתיקה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 39, 'paragraph', 'הערות
• סדר הביקורים עשוי להשתנות בהתאם ללוחות הזמנים ולתנאים המקומיים.
• התוכנית משלבת היסטוריה, תרבות, מורשת יהודית, אדריכלות ומפגש בלתי אמצעי עם אחת המדינות המיוחדות והמרתקות בעולם.
• הטיול מיועד למבקשים להעמיק מעבר לאתרי החובה ולהכיר את הסיפורים, האנשים והתרבויות שהפכו את אוזבקיסטן לאחת הפנינים הנסתרות של אסיה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 40, 'heading', 'תאריכי יציאה ומחירים', 2, '["cost"]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 41, 'paragraph', '13/04/27 – 05/04/27', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 42, 'paragraph', 'טיסות ישירות תל אביב – טשקנט – תל אביב', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 43, 'paragraph', 'עלות לאדם בחדר זוגי – 3,450$', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 44, 'paragraph', 'הנחה של 200$ לנוסע לנרשמים עד ה 15/11/2026', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 45, 'paragraph', 'המחיר כולל:', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 46, 'list', null, null, '[]', '[]', false, '[{"text":"טיסות ישורות","links":[],"children":[]},{"text":"טיסות פנים","links":[],"children":[]},{"text":"רכבות מהירות","links":[],"children":[]},{"text":"בתי מלון ברמת בוטיק","links":[],"children":[]},{"text":"ארוחת בוקר וערב","links":[],"children":[]},{"text":"כניסה לכל האתרים על פי התכנית","links":[],"children":[]},{"text":"אוטובוס צמוד","links":[],"children":[]},{"text":"מדריך מקצועי ובעל ידע רחב, מומחה לאיסלאם, ד״ר רחלי קרייסברג","links":[],"children":[]},{"text":"מדריך מקומי","links":[],"children":[]},{"text":"מלווה ישראלי שהינו מורה דרך מוסמך של משרד התיירות ובעל ניסיון רב","links":[],"children":[]},{"text":"קבוצה קטנה","links":[],"children":[]},{"text":"מפגש מטיילים בזום לפני הטיול","links":[],"children":[]}]', null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 47, 'paragraph', 'מה לא כלול?', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 48, 'list', null, null, '[]', '[]', false, '[{"text":"ביטוח בריאות ומטען (חובה)","links":[],"children":[]},{"text":"הוצאות אישיות","links":[],"children":[]},{"text":"כל מה שלא נכלל בתכנית הטיול","links":[],"children":[]}]', null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 49, 'heading', 'תנאים והערות', 2, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 50, 'paragraph', 'תנאי תשלום', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 51, 'paragraph', 'עם ההרשמה תשלום ראשון על סך 3000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 52, 'paragraph', '90 יום לפני מועד הטיול תשלום שני סך 4000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 53, 'paragraph', '60 יום לפני מועד הטיול יתרת כל הסכום', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 54, 'paragraph', 'התשלום יבוצע בהוראת קבע או מזומן', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 55, 'paragraph', 'כל תשלום יחושב לפי שער הדולר האמריקאי מכירה מזומן בבנק הפועלים ביום התשלום', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 56, 'paragraph', 'תנאי ביטול', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 57, 'paragraph', 'מיום ההרשמה ועד 14 יום ללא דמי ביטול ובלבד שנותרו יותר מ 60 יום למועד הטיול', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 58, 'paragraph', '45-60 יום לפני מועד הטיול דמי ביטול 1000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 59, 'paragraph', '44-30 יום לפני מועד הטיול דמי ביטול 3000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 60, 'paragraph', '29-15 יום לפני מועד הטיול דמי ביטול 5000 ש”ח', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 61, 'paragraph', '14 יום ופחות עד מועד הטיול דמי הביטול הינם כל סכום עלות הטיול ללא החזר', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 62, 'paragraph', 'כל החזר בגין ביטול טיול יבוצע בהעברה בנקאית לחשבון ממנו התקבל התשלום', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 63, 'paragraph', 'תנאים ומדיניות המארגנים', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 64, 'paragraph', 'תנאים אלו הינם חלק בלתי נפרד מההזמנה ומהוים חוזה בין טיולי העולם העתיק המארגנים או מי מטעמם לבין הלקוח.בעצם הרשמותו של מטייל מבטאים הסכמה מפורשת לתנאים המפורטים להלן.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 65, 'paragraph', 'טיולי העולם העתיק מזמינים שירותים שונים בחו”ל על פי הצורך לכל טיול.אנו מתחייבים לבצע הזמנת שירותים בחו”ל במיומנות בהקפדה יתרה.אנו נוודא לכל טיול את התנאים על מנת למנוע שיבושים ותקלות.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 66, 'paragraph', 'טיולי העולם העתיק או מי מטעמם לא יהיה אחראי לשיבושים ותקלות בלתי צפויים שאינם בשליטתה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 67, 'paragraph', 'טיולי העולם העתיק לא תהיה אחראית לגבי ספקי השירות השונים בכל דבר ועניין לרבות חברות התעופה, המלונות,סידורי הקרקע,השייט,בתי המלון,אשרות כניסה וכדומה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 68, 'paragraph', 'סדר ימי הטיול, האתרים,המסלול, המלונות ועוד יכולים להשתנות על פי שיקולי המדריך ולטובת הנוסעים וזאת ללא הודעה מראש', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 69, 'paragraph', 'כח עליון', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 70, 'paragraph', 'במידה והטיול לא יצא כמתוכנן בשל כוח עליון לרבות מזג אויר,אסון טבע,מצב בטחוני,אנו נספק אלטרנטיבה ראוייה או לחילופין זיכוי עתידי. לא יינתן החזר כספי.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 71, 'paragraph', 'במידה ויש צורך בויזה ולא התקבלה ויזה במועד יחויב הלקוח בדמי ביטול על פי מדיניות הביטול שלנו.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 72, 'paragraph', 'חיסונים ובריאות', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 73, 'paragraph', 'על הלקוח מוטלת האחריות הבלעדית לוודא מול משרד הבריאות או כל גורם אחר אשר יראה לנכון את הצורך בחיסונים שונים במידת הצורך', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 74, 'paragraph', 'חובה לקנות ביטוח רפואי עם ההרשמות לטיול.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 75, 'paragraph', 'אנו ממליצים להרחיב את הביטוח גם לביטוח מטען וביטול טיול על פי תנאי הפוליסה בחברות השונות.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 76, 'paragraph', 'טיסות', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 77, 'paragraph', 'יש לוודא את תנאי הכבודה בכל טיול. אנו נציין בכל טיול מה כולל וכל שמעבר למשקל הכלול או למספר המזוודות יהיה על חשבון הלקוח.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 78, 'paragraph', 'אין אפשרות לשמור מקומות ישיבה מראש וייתכן אף שבני זוג יושבו בכיסאות נפרדים.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 79, 'paragraph', 'שינוי שם או אות לאחר ההרשמה עשוי לגרום לתוספת משמעותית בעלות כרטיס הטיסה שיחולו על הלקוח.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 80, 'paragraph', 'טיולי העולם העתיק רשאים להחליף מדריך לפי הצורך ועל פי שיקול דעתה והדבר לא יהווה עילה לביטול הטיול.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 81, 'paragraph', 'ביצוע הטיול מותנה במינימום משתתפים במידה ולא יצא הטיול מסיבה זאת. טיולי העולם העתיק תחזיר את כל הכספים ששולמו למעט הוצאת ויזה באם הייתה כזאת ולא תהיה כל טענה נוספת כלפי טיולי העולם העתיק או מי מטעמה', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 82, 'paragraph', 'המחיר כולל:', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 83, 'list', null, null, '[]', '[]', false, '[{"text":"טיסות ישורות","links":[],"children":[]},{"text":"טיסות פנים","links":[],"children":[]},{"text":"רכבות מהירות","links":[],"children":[]},{"text":"בתי מלון ברמת בוטיק","links":[],"children":[]},{"text":"ארוחת בוקר וערב","links":[],"children":[]},{"text":"כניסה לכל האתרים על פי התכנית","links":[],"children":[]},{"text":"אוטובוס צמוד","links":[],"children":[]},{"text":"מדריך מקצועי ובעל ידע רחב, מומחה לאיסלאם, ד״ר אייל מירון","links":[],"children":[]},{"text":"מדריך מקומי","links":[],"children":[]},{"text":"מלווה ישראלי שהינו מורה דרך מוסמך של משרד התיירות ובעל ניסיון רב","links":[],"children":[]},{"text":"קבוצה קטנה","links":[],"children":[]},{"text":"מפגש מטיילים בזום לפני הטיול","links":[],"children":[]}]', null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 84, 'paragraph', 'מה לא כלול?', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 85, 'list', null, null, '[]', '[]', false, '[{"text":"ביטוח בריאות ומטען (חובה)","links":[],"children":[]},{"text":"הוצאות אישיות","links":[],"children":[]},{"text":"כל מה שלא נכלל בתכנית הטיול","links":[],"children":[]}]', null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 86, 'heading', 'למה לטייל איתנו', 2, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 87, 'paragraph', 'טיולי העולם העתיק הינו עסק פרטי המנוהל על ידי מורה דרך מוסמכים מטעם משרד התיירות. אנו מארגנים טיולי בוטיק גאוגרפיים ולימודיים בארצות העולם העתיק ומעבר. בטיולנו אנו דואגים לרמה גבוהה של שירותים מקומיים ולדבר החשוב ביותר ההדרכה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 88, 'paragraph', 'הדרכה בטיול יכולה להיות קרדינלית להנאה בטיול. בסמוך ולפני כל טיול אנו חוקרים שוב את האתרים בשטח כי מידיי פעם ישנם שינויים ולכן אנו דואגים להיות מעודכנים ולתת למטילנו את המיטב ולנצל את זמן הטיול באופן היעיל ביותר ומבלי לבזבז זמן עקב שינויים מבאתרים השונים.
עקב העובדה שהכל מתבצע על ידינו באופן אישי אנו זמינים 24/7 לכל שאלה/ בקשה או עזרה בכל נושא.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 89, 'paragraph', 'מאחר ואנו אשר בוחרים מאת המסלול והאתרים בפינצטה (ישנם הרבה אתרים פופולריים שקיבלו הרבה יחסי ציבור אבל בעצם אין בהם ממש) על פי שיקולנו המקצועיים ולא על פי אינטרסים כלכליים של נותני השירותים בחו”ל. הלקוח נהנה מטיול שהינו כטיול פרטי ומקבל תמורה מלאה לכספו.
כך יש באפשרותנו להיות גמישים בכל דבר ועניין בעת הצורך. גנמישות זאת הינה הכרכית בטיולים בכלל ובטיולים מאורגנים בפרט. אין אנו צריכים לקבל אישור מהנהלת החברה בארץ (כי אנו ההנהלה שנמצאת עימכם).או כל דבר בירוקרטי אחר.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 90, 'paragraph', 'אנו גם מתכנני הטיול גם המשווקים גם המדריכים וגם המלווים כך שתמיד הלקוח נמצא בקשר ישיר איתנו ללא צורך במתווכים על כל המתמע מכך.
בהדרכה אחד הדברים החשובים ביותר בטיול בפרט לאיזורים עם הסטוריה עשירה כמו יוון, איטליה,מצרים,סין חשוב שהמדריך יהיה מקצועי מומחה וגם מעביר את החומר באופן שינעם למטייל בחביבות ובנעימות עם חוש הומור ולכן אנו בוחרים את מדריכנו בקפידה ייתרה.', null, '[]', '[]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 91, 'paragraph', 'מסלול יומי', null, '[]', '[{"text":"מסלול יומי","href":"/tours/uzbekistan-april-2027/#journy"}]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 92, 'paragraph', 'מחיר ותנאים', null, '[]', '[{"text":"מחיר ותנאים","href":"/tours/uzbekistan-april-2027/#cost"}]', null, null, null, null),
('page-1259e55f-578c-4db2-90b6-274d43d51283', 93, 'paragraph', 'צור קשר', null, '[]', '[{"text":"צור קשר","href":"/tours/uzbekistan-april-2027/#lead"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 0, 'heading', 'טיול מאורגן לאוזבקיסטן – מסע מרתק אל ליבה של דרך המשי', 2, '[]', '[{"text":"טיול מאורגן לאוזבקיסטן – מסע מרתק אל ליבה של דרך המשי","href":"/blog/uzbekistan-silk-road/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 1, 'paragraph', 'אוזבקיסטן היא אחת ההפתעות הגדולות של עולם התיירות. במשך מאות שנים היא הייתה הלב הפועם של דרך המשי – רשת הדרכים העתיקה שחיברה בין סין, הודו, פרס, המזרח התיכון ואירופה. דרך עריה עברו סוחרים, חוקרים, מלומדים ושליטים, שהביאו עמם סחורות, רעיונות, דתות ותרבויות אשר עיצבו את ההיסטוריה האנושית. כיום, מטיילים מכל העולם מגלים מחדש את […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 2, 'heading', 'טיול מאורגן לסין – מסע תרבותי אל ליבה של האימפריה הסינית', 2, '[]', '[{"text":"טיול מאורגן לסין – מסע תרבותי אל ליבה של האימפריה הסינית","href":"/blog/china-cultural-journey/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 3, 'paragraph', 'לטייל כדי להבין את סין וכדי לחוש את סין מה עומד מאחורי הקסם הסיני -? זה חלון הזדמנויות קטן וכדאי לנצלו עכשיו לטיול מאורגן בסין, המדינה המאוכלסת בעולם, מציעה עומק תרבותי, פילוסופי והיסטורי שאין שני לו. טיול מאורגן לסין הוא לא עוד נופש – זהו מסע אינטימי אל תוך התרבות, האדריכלות, המחשבה והנופים של אחת […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 4, 'heading', 'טיול מאורגן לסין – חוויה של פעם בחיים', 2, '[]', '[{"text":"טיול מאורגן לסין – חוויה של פעם בחיים","href":"/blog/china-experience/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 5, 'paragraph', 'סין היא מדינה עוצרת נשימה – אדירה בגודלה, עשירה בתרבות, מגוונת בנופים, ומפתיעה בכל צעד. עם היסטוריה של למעלה מ-3,500 שנה, שפה מוסיקלית וייחודית, דתות ופילוסופיות ששינו את פני המזרח, טיול מאורגן לסין הוא הרבה מעבר לחופשה – זהו מסע לעולם אחר, מרתק ועמוק. למה לבחור דווקא בטיול מאורגן לסין? סין היא מדינה מורכבת לתייר […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 6, 'heading', 'בייג’ינג – בירת סין', 2, '[]', '[{"text":"בייג’ינג – בירת סין","href":"/blog/beijing/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 7, 'paragraph', 'בייג’ינג – בירת סין והלב הפועם של התרבות הסינית בייג’ינג, בירתה של סין, היא עיר המשלבת בין ההיסטוריה העתיקה לבין הקדמה והמודרניזציה. טיול לבייג’ינג הוא מסע מרתק החושף את המבקרים לתרבות עשירה והיסטוריה מרשימה, לצד חוויות מודרניות וחדשניות. בייג’ינג היא עיר מגוונת המשלבת בין מסורת סינית עתיקה להשפעות מערביות מודרניות. זוהי עיר צפופה המונה כ-21 […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 8, 'heading', 'אתונה – בירת יוון והלב הפועם של התרבות המערבית', 2, '[]', '[{"text":"אתונה – בירת יוון והלב הפועם של התרבות המערבית","href":"/blog/athens/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 9, 'paragraph', 'אתונה – בירת יוון והלב הפועם של התרבות המערבית אתונה, בירתה של יוון, היא עיר המשלבת באופן יוצא דופן בין העבר המפואר לעידן המודרני. טיול לאתונה הוא מסע מרתק החושף את המבקרים לתרבות עשירה, היסטוריה עתיקת יומין ואורח חיים מודרני ותוסס. אתונה היא עיר מגוונת המשקפת את השפעתה של התרבות היוונית הקלאסית לצד נגיעות אירופאיות […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 10, 'heading', 'חמישה דברים שלא ידעתם על סין העתיקה', 2, '[]', '[{"text":"חמישה דברים שלא ידעתם על סין העתיקה","href":"/blog/ancient-china-facts/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 11, 'paragraph', 'חמישה דברים שלא ידעתם על סין העתיקה סין העתיקה היא אחת מהתרבויות העתיקות והמגוונות ביותר בעולם, עם היסטוריה עשירה ותרומה נרחבת לתרבות האנושית. הנה חמישה דברים מעניינים על סין העתיקה שכנראה לא ידעתם: 1. המצוינות המדעית של דינסטיית האן בתקופת שושלת האן (206 לפנה”ס – 220 לספירה), סין העתיקה חוותה פריחה מדעית וטכנולוגית. בתקופה זו […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 12, 'heading', 'חמישה דברים שלא ידעתם על יוון העתיקה', 2, '[]', '[{"text":"חמישה דברים שלא ידעתם על יוון העתיקה","href":"/blog/ancient-greece-facts/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 13, 'paragraph', 'חמש דברים שלא ידעתם על יוון העתיקה יוון העתיקה היא מקור השראה לתרבות המערבית, עם תרומות רבות בתחומים מגוונים כמו פילוסופיה, מדע, אמנות וספורט. אך מעבר לעובדות הידועות, ישנם פרטים פחות מוכרים ומרתקים על התרבות והחיים ביוון העתיקה. הנה חמש עובדות כאלו: 1. בתי ספר לאסטרונומיה בפורוס באי פורוס בצפון יוון פעלו בתי ספר לאסטרונומיה […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 14, 'heading', 'טיול לקהיר', 2, '[]', '[{"text":"טיול לקהיר","href":"/blog/cairo/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 15, 'paragraph', 'קהיר זו עיר בירתה של מצרים ולב לבה של מבקרים מכל העולם. טיול לקהיר הוא טיול מרתק במיוחד וכלל בתוכו המון אלמנטים תרבותיים והיסטוריים משולבים עם התרבות המודרנית לצד מנהגים עתיקים אשר נשמרו ועוברים מדור לדור בשלמותם. קהיר היא עיר מאוד מגוונת וכוללת בתוכה אלמנטים אפריקאים, מזרחיים ואירופאים כאחד. זו עיר צפופה מאוד המונה כ-9.6 […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 16, 'heading', 'טיול לפירמידות', 2, '[]', '[{"text":"טיול לפירמידות","href":"/blog/pyramids/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 17, 'paragraph', 'בין הסמלים המובהקים לתרבות מצרים העתיקה, הן הפירמידות המפורסמות בכל העולם אשר נבנו בתקופת הממלכה הקדומה ותקופת הממלכה התיכונה לפני אלפי שנים. הן בעלות היסטוריה מרהיבה אשר עדיין לא פוענחו עד הסוף. הפירמידות המפורסמות נבנו על ידי המצרים הקדמונים בגדתו המערבית של נהר הנילוס – ארץ המתים לפי אמונתם של מצרים. בתקופת השושלות המוקדמות במצרים […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 18, 'heading', 'טיול לסכר אסואן', 2, '[]', '[{"text":"טיול לסכר אסואן","href":"/blog/aswan-dam/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 19, 'paragraph', 'סכר אסואן הוא מערכת של שני סכרים על נהר הנילוס המכונים “סכר אסואן הגבוה” ו”סכר אסואן הנמוך” שממוקמים סמוך לאסואן שבמצרים ומשמשים לאגירת מי הנהר מאמצעות טקטיקת הצפה האזור ומספקת מי שתייה ומים להשקיה לתושבים. אסואן היא העיר הדרומית ביותר במצרים ובירת המחוז הנושא את אותו שם. אוכלוסיית העיר כוללת 379,224 בני אדם. יחד עם […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 20, 'heading', 'טיול לאלכסנדריה', 2, '[]', '[{"text":"טיול לאלכסנדריה","href":"/blog/alexandria/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 21, 'paragraph', 'טיול לאלכסנדריה זהו טיול מאוד חשוב מכלל הטיול למצרים, מכיוון שמדובר בעיר נמל של מצרים והיא עיר הכי חשובה בהיסטוריה המצרית ובעלת היסטוריה עתיקה מאוד עשירה. עיר אלכסנדריה נוסדה בידי אלכסנדר מוקדון בשנת 334 לפנה”ס והוא קרא לה על שמו. אלכסנדריה הייתה לפוליס יווני אופיינית, מלאה בגנים מרהיבים ובבנייני ציבור מאוד מפוארים לאותה התקופה. למרבה […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 22, 'heading', 'מקדשי דנדרה / זודיאק של דנדרה', 2, '[]', '[{"text":"מקדשי דנדרה / זודיאק של דנדרה","href":"/blog/dendera-zodiac/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 23, 'paragraph', 'מקדש דנדרה זהו מקדש מצרי מאוד עתיק והוא אחד מהמקדשים העתיקים השמורים ביותר במצרים שהוקדש לאלה חתחור שהיא אלת היופי והאהבה , השוכן על הגדה המערבית של נהר הנילוס כ-4 ק”מ מהנהר, כ-2.5 ק”מ דרומית-מערבית לעיר דנדרה שבמצרים העליונה, וכ-60 ק”מ צפונית ללוקסור. המקדש נבנה בתקופה התלמיית ונשלם בתקופה הרומית, והוא אחד מהמקדשים המצריים השמורים […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 24, 'heading', 'טיול לממפיס סקארה', 2, '[]', '[{"text":"טיול לממפיס סקארה","href":"/blog/memphis-saqqara/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 25, 'paragraph', 'טיול לממפיס וסקארה הוא טיול ייחודי המשלב שני אתרים היסטוריים ומשמעותיים במצריים ובתרבות המצרית. ממפיס הייתה בירת מצרים העתיקה, וסקארה הייתה עיר הקברים שלה. בממפיס נמצא פסל ענק של רעמסס השני, ובסקארה נמצאת הפירמידה הראשונה שנבנתה בהיסטוריה, הפירמידה של ג’וסר. עם חברת טיולי העולם העתיק אתם תחוו טיול מלא בחוויות בלתי נשכחות לאורך כל הטיול. הצוות […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 26, 'heading', 'טיול לכנסייה תלויה / כנסיית אל-מועלק', 2, '[]', '[{"text":"טיול לכנסייה תלויה / כנסיית אל-מועלק","href":"/blog/hanging-church/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 27, 'paragraph', 'מסע בזמן להיסטוריה העתיקה של מצרים ישאיר אתכם פעורי פה ועד לגבול הבלתי נתפס. הסיורים המרהיבים של מצרים יגרמו לכם לחוות את מצרים כמו שלא חוויתם אף פעם. עם הטיולים של חברת טיולי העולם העתיק תוכלו סוף סוף להגשים את החלום, ולטעום מיעדים מובחרים במצרים הכוללים תרבות, סיורים לאתרים היסטוריים עתיקים, שווקים, מסעדות אותנטיות ועדכניות ועוד […]', null, '[]', '[]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 28, 'heading', 'טיול לאבו סימבל', 2, '[]', '[{"text":"טיול לאבו סימבל","href":"/blog/abu-simbel/"}]', null, null, null, null),
('page-496b135a-ca6c-4c36-b312-22502e4f12e1', 29, 'paragraph', 'טיול לאבו סימבל הוא טיול קליל ומאוד כיפי לכלל המבקרים בה. אבו סימבל היא עיר קטנה ומלאה בקסם ושוכנת לא רחוק מגבול מצרים-סודאן ולצד נהר הנילוס. בעיר אבו סימבל מאוד קל לטייל בה ברגל והיא יעד נהדר לטיול יומי קליל וממלא באנרגיות טובות. אבו סימבל זהו אתר ארכיאולוגי אשר נמצא בעיר אבו סימבל והאתרים המרכזיים […]', null, '[]', '[]', null, null, null, null),
